const claimCommandAutomation = (params: {
  instanceId: number;
  chatId: string;
  messageId?: string | null;
  command?: string | null;
}) => {
  const now = Date.now();
  if (COMMAND_AUTOMATION_DEDUPE.size > COMMAND_AUTOMATION_DEDUPE_MAX) {
    for (const [key, expiresAt] of COMMAND_AUTOMATION_DEDUPE) {
      if (expiresAt <= now || COMMAND_AUTOMATION_DEDUPE.size > COMMAND_AUTOMATION_DEDUPE_MAX) {
        COMMAND_AUTOMATION_DEDUPE.delete(key);
      }
    }
  }

  const messageKey = params.messageId?.trim()
    || `${params.command ?? "command"}:${Math.floor(now / 10_000)}`;
  const key = `${params.instanceId}:${params.chatId}:${messageKey}`;
  const existingExpiresAt = COMMAND_AUTOMATION_DEDUPE.get(key);
  if (existingExpiresAt && existingExpiresAt > now) {
    return false;
  }
  COMMAND_AUTOMATION_DEDUPE.set(key, now + COMMAND_AUTOMATION_DEDUPE_TTL_MS);
  return true;
};

/**
 * Storage and webhook delivery are intentionally independent. A history sync
 * can persist a message before the live upsert arrives, so the database
 * duplicate flag cannot be used as the automation guard.
 */
const claimMessageAutomation = async (params: {
  instanceId: number;
  chatId: string;
  messageId?: string | null;
}) => {
  const messageId = params.messageId?.trim();
  if (!messageId) {
    return true;
  }

  const now = Date.now();
  if (MESSAGE_AUTOMATION_DEDUPE.size >= MESSAGE_AUTOMATION_DEDUPE_MAX) {
    for (const [key, expiresAt] of MESSAGE_AUTOMATION_DEDUPE) {
      if (expiresAt <= now || MESSAGE_AUTOMATION_DEDUPE.size >= MESSAGE_AUTOMATION_DEDUPE_MAX) {
        MESSAGE_AUTOMATION_DEDUPE.delete(key);
      }
    }
  }

  const key = `${params.instanceId}:${params.chatId}:${messageId}`;
  const localExpiresAt = MESSAGE_AUTOMATION_DEDUPE.get(key);
  if (localExpiresAt && localExpiresAt > now) {
    return false;
  }

  const distributedClaim = await redisSetIfAbsent(
    redisKey("dedupe", "message-automation", key),
    `${process.pid}:${now}`,
    MESSAGE_AUTOMATION_DEDUPE_TTL_MS,
  );
  if (distributedClaim === false) {
    return false;
  }

  MESSAGE_AUTOMATION_DEDUPE.set(key, now + MESSAGE_AUTOMATION_DEDUPE_TTL_MS);
  return true;
};

const normalizeDownloadActionValue = (value: string): string => {
  let current = String(value ?? "").trim();
  for (let i = 0; i < 2; i += 1) {
    try {
      const decoded = decodeURIComponent(current);
      if (decoded === current) break;
      current = decoded.trim();
    } catch {
      break;
    }
  }
  current = current.replace(/\s+/g, " ").trim();
  if (!current) {
    return "";
  }
  if (/^https?:\/\//i.test(current)) {
    try {
      const url = new URL(current);
      url.protocol = url.protocol.toLowerCase();
      url.hostname = url.hostname.toLowerCase();
      return url.toString();
    } catch {
      return current.toLowerCase();
    }
  }
  return canonicalizeCommandText(current) || current.toLowerCase();
};

const claimDownloadAction = (params: {
  instanceId: number;
  chatId: string;
  senderJid?: string | null;
  kind: "ytmp3" | "ytmp4";
  query: string;
}) => {
  const now = Date.now();
  if (DOWNLOAD_ACTION_DEDUPE.size > DOWNLOAD_ACTION_DEDUPE_MAX) {
    for (const [key, expiresAt] of DOWNLOAD_ACTION_DEDUPE) {
      if (expiresAt <= now || DOWNLOAD_ACTION_DEDUPE.size > DOWNLOAD_ACTION_DEDUPE_MAX) {
        DOWNLOAD_ACTION_DEDUPE.delete(key);
      }
    }
  }

  const senderKey = normalizeJid(params.senderJid) || params.senderJid || "unknown";
  const actionKey = normalizeDownloadActionValue(params.query);
  const key = `${params.instanceId}:${params.chatId}:${senderKey}:${params.kind}:${actionKey}`;
  const existingExpiresAt = DOWNLOAD_ACTION_DEDUPE.get(key);
  if (existingExpiresAt && existingExpiresAt > now) {
    return false;
  }
  DOWNLOAD_ACTION_DEDUPE.set(key, now + DOWNLOAD_ACTION_DEDUPE_TTL_MS);
  return true;
};

