const GIPHY_STICKER_PACK_AUTHOR = "botadmin.shop";
const GIPHY_STICKER_PACK_DEFAULT_QUERY = "memes";
const GIPHY_STICKER_PACK_DEFAULT_COUNT = 12;
const GIPHY_STICKER_PACK_MAX_COUNT = 25;
const GETSTICKERPACK_BASE_URL = "https://getstickerpack.com";
const GETSTICKERPACK_STICKER_PACK_AUTHOR = "botadmin.shop";
const GETSTICKERPACK_DEFAULT_QUERY = "memes";
const GETSTICKERPACK_DEFAULT_COUNT = null;
const GETSTICKERPACK_MAX_COUNT = 50;

type GiphyStickerPackSpec = {
  query: string;
  pack: string;
  count: number;
};

type StickerPackSearchSpec = {
  query: string;
  pack: string;
  count: number | null;
};

type GiphyStickerApiImage = {
  url?: string;
  webp?: string;
  mp4?: string;
};

type GiphyStickerApiItem = {
  id?: string;
  title?: string;
  slug?: string;
  images?: Record<string, GiphyStickerApiImage | undefined>;
};

type StickerPackSourceItem = {
  sticker: string;
  fileName: string;
  mimeType: string;
  emojis: string[];
  accessibilityLabel: string;
};

const firstGiphyString = (...values: unknown[]): string => {
  for (const value of values) {
    if (typeof value !== "string") continue;
    const trimmed = value.trim();
    if (trimmed) return trimmed;
  }
  return "";
};

const parseGiphyStickerPackCommand = (raw: string | null | undefined): GiphyStickerPackSpec => {
  const parts = (raw || "").trim().split(/\s+/).filter(Boolean);
  let count = GIPHY_STICKER_PACK_DEFAULT_COUNT;
  const last = parts[parts.length - 1];
  if (last && /^\d{1,2}$/.test(last)) {
    parts.pop();
    const parsed = Number.parseInt(last, 10);
    if (Number.isFinite(parsed)) {
      count = Math.min(Math.max(parsed, 1), GIPHY_STICKER_PACK_MAX_COUNT);
    }
  }
  const requestedQuery = normalizeStickerSearchQuery(parts.join(" "));
  const query = requestedQuery || GIPHY_STICKER_PACK_DEFAULT_QUERY;
  return {
    query,
    pack: requestedQuery || "BotAdmin",
    count,
  };
};

const parseStickerPackSearchCommand = (
  raw: string | null | undefined,
  options: { defaultQuery: string; defaultCount: number | null; maxCount: number },
): StickerPackSearchSpec => {
  const parts = (raw || "").trim().split(/\s+/).filter(Boolean);
  let count = options.defaultCount;
  const last = parts[parts.length - 1];
  if (last && /^\d{1,2}$/.test(last)) {
    parts.pop();
    const parsed = Number.parseInt(last, 10);
    if (Number.isFinite(parsed)) {
      count = Math.min(Math.max(parsed, 1), options.maxCount);
    }
  }
  const requestedQuery = normalizeStickerSearchQuery(parts.join(" "));
  const query = requestedQuery || options.defaultQuery;
  return {
    query,
    pack: requestedQuery || "BotAdmin",
    count,
  };
};

const fetchGiphyStickerPackItems = async (spec: GiphyStickerPackSpec) => {
  const apiKey =
    process.env.GIPHY_API_KEY?.trim() ||
    process.env.NEXT_PUBLIC_GIPHY_API_KEY?.trim() ||
    GIPHY_FALLBACK_API_KEY;
  if (!apiKey) {
    throw new Error("Chave GIPHY não configurada.");
  }

  const upstream = new URL("https://api.giphy.com/v1/gifs/search");
  upstream.searchParams.set("api_key", apiKey);
  upstream.searchParams.set("q", spec.query);
  upstream.searchParams.set("limit", String(spec.count));
  upstream.searchParams.set("rating", "pg-13");
  upstream.searchParams.set("lang", "pt");

  const response = await fetch(upstream, {
    headers: { Accept: "application/json" },
  });
  const payload = await response.json().catch(() => null);
  if (!response.ok) {
    const message =
      typeof payload?.meta?.msg === "string"
        ? payload.meta.msg
        : typeof payload?.message === "string"
          ? payload.message
          : "Falha ao consultar o GIPHY.";
    throw new Error(message);
  }

  const entries: unknown[] = Array.isArray(payload?.data) ? payload.data : [];
  return entries
    .reduce<StickerPackSourceItem[]>((acc, entry: unknown, index: number) => {
      const item = entry && typeof entry === "object" ? (entry as GiphyStickerApiItem) : null;
      const images = item?.images ?? {};
      const original = images.original ?? {};
      const fixedWidth = images.fixed_width ?? {};
      const fixedWidthSmall = images.fixed_width_small ?? {};
      const fixedHeightSmall = images.fixed_height_small ?? {};
      const downsized = images.downsized ?? {};
      const downsizedSmall = images.downsized_small ?? {};
      const preview = images.preview ?? {};
      const source = firstGiphyString(
        fixedWidthSmall.mp4,
        fixedHeightSmall.mp4,
        downsizedSmall.mp4,
        preview.mp4,
        fixedWidth.mp4,
        original.mp4,
        fixedWidthSmall.webp,
        fixedHeightSmall.webp,
        fixedWidth.webp,
        downsized.webp,
        original.webp,
      );
      if (!source) return acc;
      const isVideo = /\.mp4(?:[?#]|$)/i.test(source) || (source.includes("media") && source.includes("mp4"));
      acc.push({
        sticker: source,
        fileName: `${sanitizeStickerMetadataText(item?.id || item?.slug || `giphy-${index + 1}`) || `giphy-${index + 1}`}.webp`,
        mimeType: isVideo ? "video/mp4" : "image/webp",
        emojis: ["✨"],
        accessibilityLabel: `${spec.pack} ${index + 1}`,
      });
      return acc;
    }, [])
    .slice(0, spec.count);
};

const loadCheerioHtml = (html: string) => {
  const cheerio = (eval("require") as NodeRequire)("cheerio") as typeof import("cheerio");
  return cheerio.load(html);
};

const fetchStickerPackHtml = async (url: string): Promise<string> => {
  const response = await fetch(url, {
    headers: {
      Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
      "User-Agent": "Mozilla/5.0 BotAdmin/1.0 (+https://botadmin.shop)",
    },
  });
  if (!response.ok) {
    throw new Error(`GetStickerPack respondeu ${response.status}`);
  }
  return response.text();
};

const absoluteGetStickerPackUrl = (href: string): string | null => {
  if (!href.trim()) {
    return null;
  }
  try {
    return new URL(href, GETSTICKERPACK_BASE_URL).toString();
  } catch {
    return null;
  }
};

const inferStickerMimeFromUrl = (url: string): string => {
  const pathname = (() => {
    try {
      return new URL(url).pathname.toLowerCase();
    } catch {
      return url.toLowerCase();
    }
  })();
  if (pathname.endsWith(".gif")) return "image/gif";
  if (pathname.endsWith(".webp")) return "image/webp";
  if (pathname.endsWith(".png")) return "image/png";
  if (pathname.endsWith(".jpg") || pathname.endsWith(".jpeg")) return "image/jpeg";
  if (pathname.endsWith(".mp4")) return "video/mp4";
  return "image/webp";
};

const stickerFileNameFromUrl = (url: string, fallback: string): string => {
  try {
    const pathname = new URL(url).pathname;
    const name = path.basename(pathname);
    return sanitizeStickerMetadataText(name) || fallback;
  } catch {
    return fallback;
  }
};

const fetchGetStickerPackItems = async (
  spec: StickerPackSearchSpec,
): Promise<{ title: string; originalAuthor: string; originalAuthorLink: string | null; stickers: StickerPackSourceItem[] }> => {
  const searchUrl = new URL("/stickers", GETSTICKERPACK_BASE_URL);
  searchUrl.searchParams.set("query", spec.query);
  const html = await fetchStickerPackHtml(searchUrl.toString());
  const $ = loadCheerioHtml(html);
  const packLinks: string[] = [];
  const addPackHref = (href: string | undefined) => {
    if (!href) return;
    const absolute = absoluteGetStickerPackUrl(href);
    if (!absolute || packLinks.includes(absolute)) return;
    if (!/\/stickers\/[^/?#]+/i.test(absolute)) return;
    packLinks.push(absolute);
  };

  $("#stickerPacks > div > div:nth-child(3) > div > a").each((_, element) => {
    addPackHref($(element).attr("href"));
  });
  if (packLinks.length === 0) {
    $('a[href*="/stickers/"]').each((_, element) => {
      addPackHref($(element).attr("href"));
    });
  }
  if (packLinks.length === 0) {
    return { title: spec.pack, originalAuthor: "", originalAuthorLink: null, stickers: [] };
  }

  const packUrl = packLinks[Math.floor(Math.random() * packLinks.length)];
  const packHtml = await fetchStickerPackHtml(packUrl);
  const $$ = loadCheerioHtml(packHtml);
  const title = sanitizeStickerMetadataText($$("#intro > div > div > h1").text()) || spec.pack;
  const originalAuthor = sanitizeStickerMetadataText($$("#intro > div > div > h5 > a").text());
  const originalAuthorLink = absoluteGetStickerPackUrl($$("#intro > div > div > h5 > a").attr("href") || "") ?? null;
  const stickerUrls: string[] = [];
  const addStickerSrc = (src: string | undefined) => {
    if (!src) return;
    const cleaned = src.split("&d=")[0].trim();
    const absolute = absoluteGetStickerPackUrl(cleaned);
    if (!absolute || stickerUrls.includes(absolute)) return;
    stickerUrls.push(absolute);
  };

  $$("#stickerPack > div > div.row > div > img").each((_, element) => {
    addStickerSrc($$(element).attr("src"));
  });
  if (stickerUrls.length === 0) {
    $$("#stickerPack img[src]").each((_, element) => {
      addStickerSrc($$(element).attr("src"));
    });
  }

  const selectedStickerUrls =
    spec.count == null
      ? stickerUrls.slice(0, GETSTICKERPACK_MAX_COUNT)
      : stickerUrls.slice(0, spec.count);
  const stickers = selectedStickerUrls.map<StickerPackSourceItem>((url, index) => ({
    sticker: url,
    fileName: stickerFileNameFromUrl(url, `sticker-${index + 1}.webp`),
    mimeType: inferStickerMimeFromUrl(url),
    emojis: ["✨"],
    accessibilityLabel: `${title} ${index + 1}`,
  }));

  return { title, originalAuthor, originalAuthorLink, stickers };
};

const encodeStickerDataUrl = (buffer: Buffer): string =>
  `data:image/webp;base64,${buffer.toString("base64")}`;

const prepareStickerPackForWhatsapp = async (
  stickers: StickerPackSourceItem[],
  meta: { pack: string; author: string; packId?: string | null },
): Promise<StickerPackSourceItem[]> => {
  const prepared: StickerPackSourceItem[] = [];
  for (const [index, item] of stickers.entries()) {
    try {
      const originalFileName = item.fileName || `sticker-${index + 1}.webp`;
      const targetFileName = originalFileName.replace(/\.[^.]+$/, ".webp");
      const sourceFileName =
        item.mimeType.startsWith("video/")
          ? originalFileName.replace(/\.[^.]+$/, ".mp4")
          : originalFileName;
      const converted = await ensureStickerWebp(
        {
          kind: "url",
          url: item.sticker,
          fileName: sourceFileName,
          mimeType: item.mimeType || undefined,
        },
        {
          pack: meta.pack,
          author: meta.author,
          packId: meta.packId,
          emojis: item.emojis,
        },
      );
      if (!converted.buffer.length) {
        continue;
      }
      prepared.push({
        ...item,
        sticker: encodeStickerDataUrl(converted.buffer),
        fileName: targetFileName || `sticker-${index + 1}.webp`,
        mimeType: "image/webp",
      });
    } catch (error) {
      console.warn("[bot-events] Sticker de pacote ignorado por falha na normalização", {
        pack: meta.pack,
        fileName: item.fileName,
        source: item.sticker,
        error,
      });
    }
  }
  return prepared;
};

const sendGetStickerPackCommand = async (
  client: WuzapiClient,
  to: string,
  rawArgs: string | null | undefined,
  quoted?: { stanzaId: string; participant?: string | null } | null,
): Promise<number> => {
  const spec = parseStickerPackSearchCommand(rawArgs, {
    defaultQuery: GETSTICKERPACK_DEFAULT_QUERY,
    defaultCount: GETSTICKERPACK_DEFAULT_COUNT,
    maxCount: GETSTICKERPACK_MAX_COUNT,
  });
  const result = await fetchGetStickerPackItems(spec);
  if (result.stickers.length === 0) {
    return 0;
  }
  const pack = result.title || spec.pack;
  const packId = deriveStickerPackId(pack);
  const preparedStickers = await prepareStickerPackForWhatsapp(result.stickers, {
    pack,
    author: GETSTICKERPACK_STICKER_PACK_AUTHOR,
    packId,
  });
  if (preparedStickers.length === 0) {
    return 0;
  }
  const authorNote = result.originalAuthor ? ` Autor original: ${result.originalAuthor}.` : "";
  await sendStickerPackMessage(client, {
    to,
    stickers: preparedStickers,
    pack,
    author: GETSTICKERPACK_STICKER_PACK_AUTHOR,
    packId,
    caption: pack,
    description: `${preparedStickers.length} figurinhas obtidas do GetStickerPack.${authorNote}`,
    quoted,
  });
  return preparedStickers.length;
};

const sendGiphyStickerPackCommand = async (
  client: WuzapiClient,
  to: string,
  rawArgs: string | null | undefined,
  quoted?: { stanzaId: string; participant?: string | null } | null,
): Promise<number> => {
  const spec = parseGiphyStickerPackCommand(rawArgs);
  const stickers = await fetchGiphyStickerPackItems(spec);
  if (stickers.length === 0) {
    return 0;
  }
  const packId = deriveStickerPackId(spec.pack);
  const preparedStickers = await prepareStickerPackForWhatsapp(stickers, {
    pack: spec.pack,
    author: GIPHY_STICKER_PACK_AUTHOR,
    packId,
  });
  if (preparedStickers.length === 0) {
    return 0;
  }
  await sendStickerPackMessage(client, {
    to,
    stickers: preparedStickers,
    pack: spec.pack,
    author: GIPHY_STICKER_PACK_AUTHOR,
    packId,
    caption: spec.pack,
    description: `${preparedStickers.length} figurinhas geradas pelo BotAdmin.`,
    quoted,
  });
  return preparedStickers.length;
};

const resolveRuntimeAntispamConfig = (
  config: BotGroupAntispamConfig | null | undefined,
): BotGroupAntispamConfig => {
  const toInt = (value: unknown, fallback: number, min: number, max: number): number => {
    const parsed = Number.parseInt(String(value ?? ""), 10);
    if (!Number.isFinite(parsed)) {
      return fallback;
    }
    return Math.max(min, Math.min(max, parsed));
  };
  return {
    burstLimit: toInt(config?.burstLimit, DEFAULT_RUNTIME_ANTISPAM_CONFIG.burstLimit, 2, 50),
    burstWindowSeconds: toInt(
      config?.burstWindowSeconds,
      DEFAULT_RUNTIME_ANTISPAM_CONFIG.burstWindowSeconds,
      2,
      60,
    ),
    repeatLimit: toInt(config?.repeatLimit, DEFAULT_RUNTIME_ANTISPAM_CONFIG.repeatLimit, 2, 20),
    repeatWindowSeconds: toInt(
      config?.repeatWindowSeconds,
      DEFAULT_RUNTIME_ANTISPAM_CONFIG.repeatWindowSeconds,
      5,
      300,
    ),
    infractionResetDays: toInt(
      config?.infractionResetDays,
      DEFAULT_RUNTIME_ANTISPAM_CONFIG.infractionResetDays,
      1,
      365,
    ),
  };
};

const trackAntispamEntry = ({
  groupId,
  participant,
  text,
  links,
  mediaKind,
  config,
  now = Date.now(),
}: {
  groupId: number;
  participant: string;
  text: string;
  links: string[];
  mediaKind: string | null;
  config?: BotGroupAntispamConfig;
  now?: number;
}): {
  flagged: boolean;
  floodCount: number;
  repeatCount: number;
  signature: string;
  summary: string;
} => {
  const textSignature = normalizeAntispamText(text).slice(0, 220);
  const linkSignature = Array.from(
    new Set(
      links
        .map((link) => link.trim().toLowerCase())
        .filter((link) => link.length > 0),
    ),
  )
    .sort()
    .slice(0, 6)
    .join("|");

  const signatureParts: string[] = [];
  if (textSignature.length >= 3) {
    signatureParts.push(`t:${textSignature}`);
  }
  if (linkSignature) {
    signatureParts.push(`l:${linkSignature}`);
  }
  if (mediaKind) {
    signatureParts.push(`m:${mediaKind}`);
  }
  const signature = signatureParts.join("||");

  if (!signature) {
    return {
      flagged: false,
      floodCount: 0,
      repeatCount: 0,
      signature: "",
      summary: "",
    };
  }

  const runtimeConfig = resolveRuntimeAntispamConfig(config);
  const burstWindowMs = runtimeConfig.burstWindowSeconds * 1000;
  const repeatWindowMs = runtimeConfig.repeatWindowSeconds * 1000;
  const trackerKey = `${groupId}:${participant}`;
  const current = ANTISPAM_TRACKER.get(trackerKey) ?? [];
  const retentionMs = Math.max(ANTISPAM_HISTORY_RETENTION_MS, burstWindowMs, repeatWindowMs);
  const fresh = current.filter((entry) => now - entry.at <= retentionMs);
  fresh.push({ at: now, signature, textSignature, linkSignature });
  if (fresh.length > ANTISPAM_MAX_HISTORY) {
    fresh.splice(0, fresh.length - ANTISPAM_MAX_HISTORY);
  }
  ANTISPAM_TRACKER.set(trackerKey, fresh);

  const floodCount = fresh.filter((entry) => now - entry.at <= burstWindowMs).length;
  const signatureRepeats = fresh.filter(
    (entry) => entry.signature === signature && now - entry.at <= repeatWindowMs,
  ).length;
  const textRepeats =
    textSignature.length >= 8
      ? fresh.filter(
          (entry) =>
            entry.textSignature.length >= 8 &&
            entry.textSignature === textSignature &&
            now - entry.at <= repeatWindowMs,
        ).length
      : 0;
  const linkRepeats =
    linkSignature.length > 0
      ? fresh.filter(
          (entry) =>
            entry.linkSignature.length > 0 &&
            entry.linkSignature === linkSignature &&
            now - entry.at <= repeatWindowMs,
        ).length
      : 0;

  const repeatCount = Math.max(signatureRepeats, textRepeats, linkRepeats);
  const hasFlood = floodCount >= runtimeConfig.burstLimit;
  const hasRepeat = repeatCount >= runtimeConfig.repeatLimit;

  const summaryParts: string[] = [];
  if (hasFlood) {
    summaryParts.push(`flood=${floodCount}/${runtimeConfig.burstLimit}`);
  }
  if (hasRepeat) {
    summaryParts.push(`repeat=${repeatCount}/${runtimeConfig.repeatLimit}`);
  }
  if (summaryParts.length === 0) {
    summaryParts.push(`flood=${floodCount}/${runtimeConfig.burstLimit}`);
  }

  return {
    flagged: hasFlood || hasRepeat,
    floodCount,
    repeatCount,
    signature,
    summary: summaryParts.join(","),
  };
};

