const ADMIN_CONTACT_CACHE_TTL_MS = 60_000;
let cachedAdminContactDigits: { value: string; expiresAt: number } = { value: "", expiresAt: 0 };

const getCachedAdminContactDigits = async (): Promise<string> => {
  const now = Date.now();
  if (cachedAdminContactDigits.value && cachedAdminContactDigits.expiresAt > now) {
    return cachedAdminContactDigits.value;
  }
  try {
    const row = await getAdminWebhookRow();
    const digits = row?.phone_number ? sanitizeWhatsappDigits(row.phone_number) : "";
    cachedAdminContactDigits = { value: digits, expiresAt: now + ADMIN_CONTACT_CACHE_TTL_MS };
    return digits;
  } catch {
    cachedAdminContactDigits = { value: "", expiresAt: now + ADMIN_CONTACT_CACHE_TTL_MS };
    return "";
  }
};

const isAdminSupportContact = async (value: string | null | undefined): Promise<boolean> => {
  if (!value) {
    return false;
  }
  const adminDigits = await getCachedAdminContactDigits();
  return Boolean(adminDigits && sanitizeWhatsappDigits(value) === adminDigits);
};

const toTimestamp = (value: string | null | undefined): number => {
  if (!value) return Number.NaN;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : Number.NaN;
};

const pruneBotInterageContext = (entries: BotGroupAiMemoryEntry[]): BotGroupAiMemoryEntry[] => {
  const now = Date.now();
  const filtered = entries.filter((entry) => {
    const ts = toTimestamp(entry.createdAt);
    if (!Number.isFinite(ts)) return true;
    return now - ts <= BOT_INTERAGE_CONTEXT_TTL_MS;
  });
  return filtered.slice(-BOT_INTERAGE_CONTEXT_LIMIT);
};

const getBotInterageContext = (groupId: number): BotGroupAiMemoryEntry[] =>
  pruneBotInterageContext(BOT_INTERAGE_CONTEXT_CACHE.get(groupId) ?? []);

const appendBotInterageContext = (groupId: number, entry: BotGroupAiMemoryEntry): void => {
  const current = BOT_INTERAGE_CONTEXT_CACHE.get(groupId) ?? [];
  const next = pruneBotInterageContext([...current, entry]);
  BOT_INTERAGE_CONTEXT_CACHE.set(groupId, next);
};

const normalizeSpotifyUrl = (value: string): string | null => {
  const ensured = ensureUrl(value);
  if (!ensured) {
    return null;
  }
  const normalized = ensured.toString();
  return isSupportedAutoDownloadLink(normalized, "spotify") ? normalized : null;
};

const buildSpotifyCaption = (
  info: SpotifyTrackInfo,
  meta: { artist?: string | null; duration?: string | null; url?: string | null } = {},
): string => {
  const lines = [`🎧 *Spotify*`, `🎵 ${info.title || "Faixa"}`];
  const artist = (meta.artist ?? info.artist)?.trim();
  if (artist) {
    lines.push(`👤 ${artist}`);
  }
  const duration = (meta.duration ?? info.duration)?.trim();
  if (duration) {
    lines.push(`⏱ ${duration}`);
  }
  const url = meta.url?.trim();
  if (url) {
    lines.push(`🔗 ${url}`);
  }
  return lines.join("\n");
};

type SpotifyDetailsMode = "auto" | "manual";

const buildSpotifyDetailsMessage = (
  payload: {
    title: string;
    artist?: string | null;
    duration?: string | null;
    url?: string | null;
  },
  mode: SpotifyDetailsMode,
): string => {
  const lines = [`🔎 *Spotify Search*`, `🎵 ${payload.title}`];
  if (payload.artist) {
    lines.push(`👤 ${payload.artist}`);
  }
  if (payload.duration) {
    lines.push(`⏱ ${payload.duration}`);
  }
  if (payload.url) {
    lines.push(`🔗 ${payload.url}`);
  }
  lines.push("");
  if (mode === "auto") {
    lines.push("⏳ Aguarde, estou baixando o áudio…");
  } else {
    lines.push("💾 Para baixar esta faixa envie o comando:");
    lines.push("/spotifydl");
    lines.push("respondendo esta mensagem.");
  }
  return lines.join("\n");
};

const resolveSpotifyCommandMetadata = async (
  rawInput: string,
  options?: { forceAutoDownload?: boolean },
): Promise<SpotifyCommandMetadata> => {
  const input = rawInput.trim();
  if (!input) {
    throw new Error("Informe um termo, artista ou URL do Spotify.");
  }

  const initialUrlProvided = Boolean(normalizeSpotifyUrl(input));
  let targetUrl = normalizeSpotifyUrl(input);
  let meta: { artist?: string | null; duration?: string | null; url?: string | null } | null = null;
  let detailsMessage: string | null = null;
  let detailsThumbnail: string | null = null;

  if (!targetUrl) {
    const search = await searchSpotifyTracks(input, 1);
    const first = search.items[0];
    const normalized = normalizeSpotifyUrl(first.url) ?? first.url;
    targetUrl = normalized;
    meta = {
      artist: first.artist,
      duration: first.duration,
      url: normalized,
    };
    detailsMessage = buildSpotifyDetailsMessage({
      title: first.title,
      artist: first.artist,
      duration: first.duration,
      url: first.url,
    }, options?.forceAutoDownload || initialUrlProvided ? "auto" : "manual");
    detailsThumbnail = typeof first.thumbnail === "string" ? first.thumbnail : null;
  } else {
    meta = { url: targetUrl };
    try {
      const metaSearch = await searchSpotifyTracks(input, 1);
      const first = metaSearch.items[0];
      detailsMessage = buildSpotifyDetailsMessage(
        {
          title: first.title,
          artist: first.artist,
          duration: first.duration,
          url: first.url,
        },
        options?.forceAutoDownload || initialUrlProvided ? "auto" : "manual",
      );
      detailsThumbnail = typeof first.thumbnail === "string" ? first.thumbnail : null;
      meta = {
        artist: first.artist,
        duration: first.duration,
        url: normalizeSpotifyUrl(first.url) ?? targetUrl,
      };
      if (meta.url) {
        targetUrl = meta.url;
      }
    } catch {
      /* fallback silently */
    }
  }

  if (!targetUrl) {
    throw new Error("Não foi possível resolver a URL do Spotify.");
  }

  return {
    targetUrl,
    meta: meta ?? {},
    detailsMessage,
    detailsThumbnail,
    mode: options?.forceAutoDownload || initialUrlProvided ? "auto" : "manual",
    initialInputWasUrl: initialUrlProvided,
  };
};

type PendingSpotifyEntry = {
  metadata: SpotifyCommandMetadata;
  expiresAt: number;
  chatId: string;
  messageId?: string | null;
};

const pendingSpotifyDownloadsByChat = new Map<string, PendingSpotifyEntry>();
const pendingSpotifyDownloadsByMessage = new Map<string, PendingSpotifyEntry>();
const PENDING_SPOTIFY_TTL_MS = 5 * 60_000;

const registerPendingSpotifyEntry = (entry: PendingSpotifyEntry) => {
  pendingSpotifyDownloadsByChat.set(entry.chatId, entry);
  if (entry.messageId) {
    pendingSpotifyDownloadsByMessage.set(entry.messageId, entry);
  }
};

const removePendingSpotifyEntry = (entry: PendingSpotifyEntry) => {
  if (pendingSpotifyDownloadsByChat.get(entry.chatId) === entry) {
    pendingSpotifyDownloadsByChat.delete(entry.chatId);
  }
  if (entry.messageId && pendingSpotifyDownloadsByMessage.get(entry.messageId) === entry) {
    pendingSpotifyDownloadsByMessage.delete(entry.messageId);
  }
};

const setPendingSpotifyEntry = (chatId: string, metadata: SpotifyCommandMetadata, messageId?: string | null) => {
  const entry: PendingSpotifyEntry = {
    metadata,
    expiresAt: Date.now() + PENDING_SPOTIFY_TTL_MS,
    chatId,
    messageId: messageId ?? null,
  };
  registerPendingSpotifyEntry(entry);
};

const consumePendingSpotifyEntry = (chatId: string, quotedMessageId?: string | null): SpotifyCommandMetadata | null => {
  if (quotedMessageId) {
    const entry = pendingSpotifyDownloadsByMessage.get(quotedMessageId);
    if (entry) {
      if (entry.expiresAt < Date.now()) {
        removePendingSpotifyEntry(entry);
        return null;
      }
      removePendingSpotifyEntry(entry);
      return entry.metadata;
    }
  }
  const entry = pendingSpotifyDownloadsByChat.get(chatId);
  if (!entry) {
    return null;
  }
  if (entry.expiresAt < Date.now()) {
    removePendingSpotifyEntry(entry);
    return null;
  }
  removePendingSpotifyEntry(entry);
  return entry.metadata;
};

const downloadSpotifyCommand = async (metadata: SpotifyCommandMetadata): Promise<SpotifyCommandResolution> => {
  const track = await downloadSpotifyTrack(metadata.targetUrl);
  return {
    downloadUrl: track.downloadUrl,
    filename: formatSpotifyFilename(track.title),
    caption: buildSpotifyCaption(track, metadata.meta),
  };
};
