const formatCoverageSummary = (expiresAt: string | null): { text: string; date: string } => {
  if (!expiresAt) {
    return { text: "sem data registrada", date: "" };
  }
  const timestamp = Date.parse(expiresAt);
  if (Number.isNaN(timestamp)) {
    return { text: "sem data registrada", date: "" };
  }
  const formatted = formatDateTime(expiresAt) ?? formatDate(expiresAt);
  const verb = timestamp >= Date.now() ? "expira em" : "venceu em";
  return {
    text: formatted ? `${verb} ${formatted}` : verb,
    date: formatted ?? "",
  };
};

