const getGroupLicensePlanLabel = (durationDays: number): string => {
  if (durationDays <= 1) return "Diário";
  if (durationDays >= 365) return "Anual";
  return "Mensal";
};

const stylizeGroupPlanText = (value: string): string =>
  Array.from(value).map((char) => {
    const code = char.charCodeAt(0);
    if (code >= 65 && code <= 90) return String.fromCodePoint(0x1d468 + code - 65);
    if (code >= 97 && code <= 122) return String.fromCodePoint(0x1d482 + code - 97);
    if (code >= 48 && code <= 57) return String.fromCodePoint(0x1d7ce + code - 48);
    return char;
  }).join("");

const sortGroupLicensePlans = <T extends { durationDays: number; price: number; name: string }>(plans: T[]): T[] =>
  plans.slice().sort((left, right) => {
    const leftIndex = GROUP_LICENSE_DURATION_ORDER.indexOf(left.durationDays as (typeof GROUP_LICENSE_DURATION_ORDER)[number]);
    const rightIndex = GROUP_LICENSE_DURATION_ORDER.indexOf(right.durationDays as (typeof GROUP_LICENSE_DURATION_ORDER)[number]);
    const safeLeft = leftIndex >= 0 ? leftIndex : GROUP_LICENSE_DURATION_ORDER.length;
    const safeRight = rightIndex >= 0 ? rightIndex : GROUP_LICENSE_DURATION_ORDER.length;
    if (safeLeft !== safeRight) return safeLeft - safeRight;
    if (left.durationDays !== right.durationDays) return left.durationDays - right.durationDays;
    if (left.price !== right.price) return left.price - right.price;
    return left.name.localeCompare(right.name, "pt-BR");
  });

const pickDefaultGroupLicensePlan = <T extends { durationDays: number }>(plans: T[]): T | null =>
  plans.find((plan) => plan.durationDays === 30) ?? plans[0] ?? null;

const describeCoverage = async ({
  userId,
  group,
}: {
  userId: number;
  group?: BotGroup | null;
}): Promise<CoverageSummary> => {
  const planStatus = await getUserPlanStatus(userId);

  const planExpiry = planStatus.currentPeriodEnd ?? null;

  if (group) {
    const groupExpiry = group.metadata?.licenseExpiresAt ?? null;
    if (!groupExpiry && group.status === "active") {
      return {
        sourceLabel: "grupo ativo",
        expiryText: "ativo",
        expiryDate: "",
      };
    }
	    const coverage = formatCoverageSummary(groupExpiry);
	    return {
	      sourceLabel: groupExpiry ? "validade legada do grupo" : "perfil sem licença",
	      expiryText: coverage.text,
	      expiryDate: coverage.date,
	    };
  }

  if (!planStatus.plan) {
    const coverage = formatCoverageSummary(planExpiry);
    return {
      sourceLabel: "plano inativo",
      expiryText: coverage.text,
      expiryDate: coverage.date,
    };
  }

  const coverage = formatCoverageSummary(planExpiry);
  return {
    sourceLabel: "plano principal",
    expiryText: coverage.text,
    expiryDate: coverage.date,
  };
};

const normalizeTimeToken = (value: string): string | null => {
  if (typeof value !== "string") {
    return null;
  }
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  const match = /^([0-2]?\d):([0-5]\d)$/.exec(trimmed);
  if (!match) {
    return null;
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) {
    return null;
  }
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return null;
  }
  return `${hours.toString().padStart(2, "0")}:${minutes.toString().padStart(2, "0")}`;
};

const sanitizeAdTimes = (entries: Iterable<string>): string[] => {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const entry of entries) {
    const normalized = normalizeTimeToken(entry);
    if (!normalized || seen.has(normalized)) {
      continue;
    }
    seen.add(normalized);
    out.push(normalized);
    if (out.length >= 10) {
      break;
    }
  }
  return out;
};

const parseAdScheduleInput = (
  raw: string,
): {
  scheduleType: "frequency" | "times";
  frequency: string;
  times: string[];
  mentionAll: boolean;
  remainingText: string;
} => {
  const defaults = {
    scheduleType: "frequency" as const,
    frequency: "24h",
    times: [] as string[],
    mentionAll: false,
    remainingText: "",
  };
  if (!raw || typeof raw !== "string") {
    return { ...defaults };
  }

  let working = raw.trim();
  let mentionAll = false;
  if (/@todos|@all/gi.test(working)) {
    mentionAll = true;
    working = working.replace(/@todos|@all/gi, " ");
  }

  const timeMatches = working.match(/([0-2]?\d:[0-5]\d)/g) ?? [];
  const sanitizedTimes = sanitizeAdTimes(timeMatches);
  if (sanitizedTimes.length > 0) {
    for (const time of sanitizedTimes) {
      const timeRegex = new RegExp(`\\b${time.replace(":", "\\:")}\\b`, "gi");
      working = working.replace(timeRegex, " ");
    }
    return {
      scheduleType: "times",
      frequency: defaults.frequency,
      times: sanitizedTimes,
      mentionAll,
      remainingText: working.replace(/\s+/g, " ").trim(),
    };
  }

  const freqMatch = working.match(/(\d{1,4}[mhd])/i);
  let frequency = freqMatch ? freqMatch[1].toLowerCase() : defaults.frequency;
  if (freqMatch) {
    working = working.replace(freqMatch[0], " ");
  } else {
    frequency = defaults.frequency;
  }

  return {
    scheduleType: "frequency",
    frequency,
    times: [],
    mentionAll,
    remainingText: working.replace(/\s+/g, " ").trim(),
  };
};

const formatAdScheduleSummary = (ad: BotGroupAd): string => {
  if (ad.scheduleType === "times") {
    const list = Array.isArray(ad.times) && ad.times.length > 0 ? sanitizeAdTimes(ad.times) : [];
    return list.length > 0 ? `Horários: ${list.join(", ")}` : "Horários: nenhum horário definido";
  }
  const pieces = parseAdScheduleInput(ad.frequency ?? "24h");
  const frequency = pieces.frequency ?? "24h";
  const unit = frequency.slice(-1);
  const numeric = frequency.slice(0, -1) || "24";
  const unitLabel = unit === "m" ? "minuto(s)" : unit === "h" ? "hora(s)" : "dia(s)";
  return `Frequência: a cada ${numeric} ${unitLabel}`;
};

