const NSFW_HARD_DELETE_THRESHOLD = {
  porn: 0.93,
  hentai: 0.9,
  total: 0.9,
} as const;

const NSFW_STRONG_SIGNAL_THRESHOLD: Record<
  NsfwGuardKind,
  { porn: number; hentai: number; sexy: number; total: number }
> = {
  image: { porn: 0.82, hentai: 0.78, sexy: 0.74, total: 0.8 },
  sticker: { porn: 0.8, hentai: 0.76, sexy: 0.7, total: 0.78 },
};

