const resolveNsfwDominantCategory = (scores: {
  porn: number;
  hentai: number;
  sexy: number;
}): { dominant: "porn" | "hentai" | "sexy"; dominantScore: number } => {
  const ranked = [
    ["porn", Number(scores.porn) || 0],
    ["hentai", Number(scores.hentai) || 0],
    ["sexy", Number(scores.sexy) || 0],
  ] as const;
  ranked.sort((left, right) => right[1] - left[1]);
  return {
    dominant: ranked[0]?.[0] ?? "porn",
    dominantScore: ranked[0]?.[1] ?? 0,
  };
};

const resolveNsfwAutoDeleteDecision = (
  kind: NsfwGuardKind,
  scores: { porn: number; hentai: number; sexy: number; nsfw: number },
): { shouldDelete: boolean; reason: "hard_threshold" | "strong_signals" | "below_threshold" } => {
  const porn = Number(scores.porn) || 0;
  const hentai = Number(scores.hentai) || 0;
  const sexy = Number(scores.sexy) || 0;
  const total = Number(scores.nsfw) || 0;
  const hardHit =
    porn >= NSFW_HARD_DELETE_THRESHOLD.porn ||
    hentai >= NSFW_HARD_DELETE_THRESHOLD.hentai ||
    total >= NSFW_HARD_DELETE_THRESHOLD.total;
  if (hardHit) {
    return { shouldDelete: true, reason: "hard_threshold" };
  }

  const threshold = NSFW_STRONG_SIGNAL_THRESHOLD[kind];
  const strongSignals =
    Number(porn >= threshold.porn) +
    Number(hentai >= threshold.hentai) +
    Number(sexy >= threshold.sexy) +
    Number(total >= threshold.total);

  if (strongSignals >= 2) {
    return { shouldDelete: true, reason: "strong_signals" };
  }

  return { shouldDelete: false, reason: "below_threshold" };
};

const isStrictModerationLink = (value: string): boolean => {
  const trimmed = (value || "").trim();
  if (!trimmed) {
    return false;
  }
  if (isGroupInviteLink(trimmed)) {
    return true;
  }

  const hasProtocol = /^https?:\/\//i.test(trimmed);
  const hasWwwPrefix = /^www\./i.test(trimmed);
  const parsed = ensureUrl(trimmed);
  if (!parsed) {
    return false;
  }
  const host = parsed.hostname.toLowerCase().replace(/^www\./, "");
  if (!host.includes(".") || /[_\s]/.test(host)) {
    return false;
  }

  const labels = host.split(".").filter(Boolean);
  if (labels.length < 2) {
    return false;
  }
  const tld = labels[labels.length - 1] ?? "";
  const secondLevel = labels.length >= 2 ? `${labels[labels.length - 2]}.${tld}` : "";
  const allowByKnownSuffix = MODERATION_STRICT_TLDS.has(tld) || MODERATION_STRICT_TLDS.has(secondLevel);
  const allowByCountryCode = /^[a-z]{2}$/i.test(tld);
  const hasValidExplicitTld = /^[a-z0-9-]{2,63}$/i.test(tld);
  if (hasProtocol || hasWwwPrefix) {
    return allowByKnownSuffix || allowByCountryCode || hasValidExplicitTld;
  }

  // Links vindos de campos explícitos do webhook podem chegar como domínio seco
  // em botões interativos, por exemplo "njr7.org".
  return allowByKnownSuffix || allowByCountryCode;
};

const ZERO_WIDTH_CHARS_REGEX = /[\u200b-\u200f\u202a-\u202e\u2060\u2061\u2062\u2063\u2064\uFEFF]/gu;
const FANCY_CHAR_MAP: Record<string, string> = {
  𝘢: "a",
  𝘣: "b",
  𝘤: "c",
  𝘥: "d",
  𝘦: "e",
  𝘧: "f",
  𝘨: "g",
  𝘩: "h",
  𝘪: "i",
  𝘫: "j",
  𝘬: "k",
  𝘭: "l",
  𝘮: "m",
  𝘯: "n",
  𝘰: "o",
  𝘱: "p",
  𝘲: "q",
  𝘳: "r",
  𝘴: "s",
  𝘵: "t",
  𝘶: "u",
  𝘷: "v",
  𝘸: "w",
  𝘹: "x",
  𝘺: "y",
  𝘻: "z",
  𝘈: "A",
  𝘉: "B",
  𝘊: "C",
  𝘋: "D",
  𝘌: "E",
  𝘍: "F",
  𝘎: "G",
  𝘏: "H",
  𝘐: "I",
  𝘑: "J",
  𝘒: "K",
  𝘓: "L",
  𝘔: "M",
  𝘕: "N",
  𝘖: "O",
  𝘗: "P",
  𝘘: "Q",
  𝘙: "R",
  𝘚: "S",
  𝘛: "T",
  𝘜: "U",
  𝘝: "V",
  𝘞: "W",
  𝘟: "X",
  𝘠: "Y",
  𝘡: "Z",
};
const FANCY_CHAR_REGEX = new RegExp(`[${Object.keys(FANCY_CHAR_MAP).join("")}]`, "g");
const DOT_WORD_REGEX = /(?:\(|\[|\{)?\s*(?:dot|d0t|ponto|p0nto)\s*(?:\)|\]|\})?/gi;
const SLASH_WORD_REGEX = /(?:\(|\[|\{)?\s*(?:slash|barra)\s*(?:\)|\]|\})?/gi;
const COLON_WORD_REGEX = /(?:\(|\[|\{)?\s*(?:colon|dois\s*pontos|doispontos)\s*(?:\)|\]|\})?/gi;

const normalizeObfuscatedLinkText = (raw: string): string => {
  if (!raw) {
    return raw;
  }

  let text = raw.replace(ZERO_WIDTH_CHARS_REGEX, "");
  // Normalize composed characters
  text = text.normalize("NFKC");
  text = text.replace(FANCY_CHAR_REGEX, (char) => FANCY_CHAR_MAP[char] ?? char);

  // Replace textual tokens for separators
  text = text.replace(DOT_WORD_REGEX, ".");
  text = text.replace(SLASH_WORD_REGEX, "/");
  text = text.replace(COLON_WORD_REGEX, ":");

  // Normalize spaced-out protocol patterns (http/https)
  text = text.replace(/h[\s._-]*x[\s._-]*x[\s._-]*p/gi, (match) =>
    match.toLowerCase().includes("s") ? "https" : "http",
  );
  text = text.replace(/h[\s._-]*t[\s._-]*t[\s._-]*p[\s._-]*s?/gi, (match) => {
    const normalized = match.replace(/[\s._-]*/g, "");
    return normalized.toLowerCase().includes("s") ? "https" : "http";
  });
  text = text.replace(/w[\s._-]*w[\s._-]*w[\s._-]*\s*(?=[./])/gi, "www");

  // Remove spaces around common URL separators
  text = text.replace(/\s*([.:/@-])\s*/g, "$1");

  return text;
};

const API_KEY_CACHE_TTL_MS = 5 * 60 * 1000;
const userApiKeyCache = new Map<number, { apiKey: string; expiresAt: number }>();

const getUserRestApiKey = async (userId: number): Promise<string | null> => {
  const cached = userApiKeyCache.get(userId);
  if (cached && cached.expiresAt > Date.now() && cached.apiKey) {
    return cached.apiKey;
  }
  try {
    const record = await getOrCreateUserApiKey(userId);
    userApiKeyCache.set(userId, {
      apiKey: record.apiKey,
      expiresAt: Date.now() + API_KEY_CACHE_TTL_MS,
    });
    return record.apiKey;
  } catch (error) {
    console.error("[bot-events] failed to resolve user API key", { userId, error });
    userApiKeyCache.delete(userId);
    return null;
  }
};

const getRestInternalBaseUrl = (): string => {
  const explicit = process.env.REST_INTERNAL_BASE_URL?.trim();
  if (explicit) {
    return explicit.replace(/\/+$/, "");
  }
  const port = process.env.PORT?.trim() || "4322";
  return `http://127.0.0.1:${port}`;
};

const fetchRestDownloadCommand = async (
  kind: "ytmp3" | "ytmp4",
  query: string,
  options: { apiKey?: string } = {},
): Promise<YtPlayResult> => {
  const buildQueryCandidates = (value: string): string[] => {
    const trimmed = value.trim();
    if (!trimmed) {
      return [];
    }

    const normalizedAscii = trimmed
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/\s+/g, " ")
      .trim();

    const compact = normalizedAscii
      .replace(/\b(baixa(?:r)?|baixar|musica|musica|música|video|vídeo|audio|áudio|mp3|mp4|pra|para|mim|no caso|por favor)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();

    return Array.from(
      new Set(
        [trimmed, normalizedAscii, compact].filter(
          (candidate) => candidate.length > 0,
        ),
      ),
    );
  };

  const baseUrl = getRestInternalBaseUrl();
  const path = kind === "ytmp3" ? "/api/rest/ytmp3" : "/api/rest/ytmp4";
  const searchPath = "/api/rest/ytsearch";
  const headers: Record<string, string> = { accept: "application/json" };
  if (options.apiKey) {
    headers["x-api-key"] = options.apiKey;
  }

  const fetchSearchFallback = async (value: string): Promise<string[]> => {
    const url = new URL(searchPath, baseUrl);
    url.searchParams.set("q", value);
    try {
      const resp = await fetch(url.toString(), { headers });
      let data: any = null;
      try {
        data = await resp.json();
      } catch {
        return [];
      }
      if (!resp.ok) {
        return [];
      }
      const entries = [
        ...(Array.isArray(data?.items) ? data.items : []),
        ...(Array.isArray(data?.resultados) ? data.resultados : []),
        ...(Array.isArray(data?.results) ? data.results : []),
        ...(Array.isArray(data?.resultado) ? data.resultado : []),
      ].slice(0, 5);
      const candidates: string[] = [];
      for (const entry of entries) {
        const urlValue =
          typeof entry?.url === "string" && entry.url.trim().length > 0
            ? entry.url.trim()
            : null;
        const titleValue =
          typeof entry?.title === "string" && entry.title.trim().length > 0
            ? entry.title.trim()
            : null;
        if (urlValue) {
          candidates.push(urlValue);
        }
        if (titleValue) {
          candidates.push(titleValue);
        }
      }
      return Array.from(new Set(candidates));
    } catch {
      return [];
    }
  };

  const attempts = buildQueryCandidates(query);
  let lastError: Error | null = null;
  let searchFallbackAttempted = false;

  for (const candidate of attempts) {
    const url = new URL(path, baseUrl);
    url.searchParams.set("q", candidate);
    try {
      const resp = await fetch(url.toString(), { headers });
      let data: any = null;
      try {
        data = await resp.json();
      } catch {
        /* ignore */
      }
      if (resp.ok && data?.resultado?.url) {
        return data.resultado as YtPlayResult;
      }

      const message =
        data?.message ||
        data?.mensagem ||
        `Falha ao baixar ${kind.toUpperCase()} (${resp.status})`;
      lastError = new Error(message);
      const normalizedMessage = String(message).toLowerCase();
      if (
        normalizedMessage.includes("nenhum resultado") &&
        !searchFallbackAttempted
      ) {
        searchFallbackAttempted = true;
        const fallbackQueries = await fetchSearchFallback(candidate);
        let appended = false;
        for (const fallbackQuery of fallbackQueries) {
          if (!attempts.includes(fallbackQuery)) {
            attempts.push(fallbackQuery);
            appended = true;
          }
        }
        if (appended) {
          continue;
        }
      }
      if (!normalizedMessage.includes("nenhum resultado")) {
        break;
      }
    } catch (error) {
      lastError =
        error instanceof Error ? error : new Error(String(error ?? "Falha ao baixar mídia"));
      if (!/^https?:\/\//i.test(baseUrl)) {
        break;
      }
    }
  }

  throw lastError ?? new Error(`Falha ao baixar ${kind.toUpperCase()}`);
};

const YOUTUBE_INLINE_AUDIO_MAX_DURATION_SECONDS = 30 * 60;
const YOUTUBE_INLINE_VIDEO_MAX_DURATION_SECONDS = 10 * 60;

const shouldSendYoutubeDownloadAsDocument = (
  kind: "ytmp3" | "ytmp4",
  result: Pick<YtPlayResult, "durationSeconds">,
): boolean => {
  const durationSeconds = Number(result.durationSeconds || 0);
  if (!Number.isFinite(durationSeconds) || durationSeconds <= 0) {
    return false;
  }
  return kind === "ytmp3"
    ? durationSeconds > YOUTUBE_INLINE_AUDIO_MAX_DURATION_SECONDS
    : durationSeconds > YOUTUBE_INLINE_VIDEO_MAX_DURATION_SECONDS;
};

const isUploadSizeError = (error: unknown): boolean => {
  const values: string[] = [];
  if (error instanceof Error) {
    values.push(error.message);
  }
  if (error && typeof error === "object") {
    const record = error as Record<string, unknown>;
    values.push(
      String(record.error ?? ""),
      String(record.message ?? ""),
      String((record.response as Record<string, unknown> | undefined)?.error ?? ""),
      String((record.response as Record<string, unknown> | undefined)?.message ?? ""),
    );
  }
  const text = values.join(" ").toLowerCase();
  return (
    text.includes("413") ||
    text.includes("too large") ||
    text.includes("request entity too large") ||
    text.includes("payload too large") ||
    text.includes("upload failed with status code 413")
  );
};

const buildYoutubeDownloadFilename = (
  result: Pick<YtPlayResult, "title" | "format">,
  fallbackBaseName: string,
): string => {
  const mime = (result.format || "").toLowerCase();
  const ext =
    mime.includes("mpeg") || mime.includes("mp3")
      ? "mp3"
      : mime.includes("webm")
        ? "webm"
        : mime.includes("mp4") && fallbackBaseName === "audio"
          ? "m4a"
          : mime.includes("mp4")
            ? "mp4"
            : fallbackBaseName === "audio"
              ? "mp3"
              : "mp4";
  return `${result.title || fallbackBaseName}.${ext}`;
};

const buildYoutubeDownloadCaption = (
  result: Pick<YtPlayResult, "title" | "author" | "durationSeconds">,
  sentAsDocument: boolean,
): string => {
  const base = [result.title, result.author].filter(Boolean).join(" — ");
  if (!sentAsDocument) {
    return base;
  }
  const durationSeconds = Number(result.durationSeconds || 0);
  const durationText = Number.isFinite(durationSeconds) && durationSeconds > 0
    ? `\nDuração: ${Math.floor(durationSeconds / 60)} min`
    : "";
  return `${base}${durationText}\nEnviado como documento porque é uma mídia longa.`;
};

const sendYoutubeDownloadMedia = async (
  client: WuzapiClient,
  params: {
    to: string;
    kind: "ytmp3" | "ytmp4";
    result: YtPlayResult;
    quoted?: SendMediaPayload["quoted"];
  },
) => {
  const mime = params.result.format || (params.kind === "ytmp3" ? "audio/mpeg" : "video/mp4");
  const fallbackBaseName = params.kind === "ytmp3" ? "audio" : "video";
  const sendAsDocument = shouldSendYoutubeDownloadAsDocument(params.kind, params.result);
  const basePayload = {
    to: params.to,
    media: params.result.url,
    filename: buildYoutubeDownloadFilename(params.result, fallbackBaseName),
    mimeType: mime,
    useExternalUrl: true,
    caption: buildYoutubeDownloadCaption(params.result, sendAsDocument),
    quoted: params.quoted,
  } satisfies Omit<SendMediaPayload, "mediaType">;

  if (sendAsDocument) {
    await sendMediaMessage(client, {
      ...basePayload,
      mediaType: "document",
    });
    return;
  }

  try {
    await sendMediaMessage(client, {
      ...basePayload,
      mediaType: params.kind === "ytmp3" ? "audio" : "video",
      durationSeconds: params.result.durationSeconds ?? undefined,
      caption: params.kind === "ytmp3" ? undefined : basePayload.caption,
    });
  } catch (error) {
    if (!isUploadSizeError(error)) {
      throw error;
    }
    await sendMediaMessage(client, {
      ...basePayload,
      mediaType: "document",
      caption: buildYoutubeDownloadCaption(params.result, true),
    });
  }
};

const fetchGenericRestDownload = async (
  endpoint: string,
  urlParam: string,
  options: { apiKey?: string } = {},
): Promise<any> => {
  const baseUrl = getAppBaseUrl();
  const target = new URL(endpoint, baseUrl);
  target.searchParams.set('url', urlParam);
  const headers: Record<string, string> = { accept: 'application/json' };
  if (options.apiKey) {
    headers["x-api-key"] = options.apiKey;
  }
  const resp = await fetch(target.toString(), { headers });
  let data: any = null;
  try { data = await resp.json(); } catch { /* ignore */ }
  if (!resp.ok || !data?.resultado?.url) {
    const message = data?.message || data?.mensagem || `Falha ao baixar mídia (${resp.status})`;
    throw new Error(message);
  }
  return data.resultado;
};

