type SimpleRestCommandConfig = {
  names: string[];
  platform: AutoDownloadPlatform;
  endpoint: string;
  mediaType: "audio" | "video";
  label: string;
};

const SIMPLE_REST_COMMANDS: SimpleRestCommandConfig[] = [
  { names: ["soundcloud"], platform: "soundcloud", endpoint: "/api/rest/soundcloud", mediaType: "audio", label: "SoundCloud" },
  { names: ["bandcamp"], platform: "bandcamp", endpoint: "/api/rest/bandcamp", mediaType: "audio", label: "Bandcamp" },
  { names: ["mixcloud"], platform: "mixcloud", endpoint: "/api/rest/mixcloud", mediaType: "audio", label: "Mixcloud" },
  { names: ["twitterspaces", "spaces"], platform: "twitterspaces", endpoint: "/api/rest/twitterspaces", mediaType: "audio", label: "Twitter Spaces" },
  { names: ["twitch"], platform: "twitch", endpoint: "/api/rest/twitch", mediaType: "video", label: "Twitch" },
  { names: ["shopee"], platform: "shopee", endpoint: "/api/rest/globalvideo", mediaType: "video", label: "Shopee" },
  { names: ["rumble"], platform: "rumble", endpoint: "/api/rest/rumble", mediaType: "video", label: "Rumble" },
  { names: ["odysee"], platform: "odysee", endpoint: "/api/rest/odysee", mediaType: "video", label: "Odysee" },
  { names: ["dailymotion"], platform: "dailymotion", endpoint: "/api/rest/dailymotion", mediaType: "video", label: "Dailymotion" },
  { names: ["instastalk"], platform: "instagram", endpoint: "/api/download/insta-stalk", mediaType: "video", label: "Instagram Stalker" },
];

const resolveSimpleRestConfig = (cmd: string): SimpleRestCommandConfig | undefined =>
  SIMPLE_REST_COMMANDS.find((entry) => entry.names.includes(cmd));

const handleSimpleRestCommand = async ({
  config,
  arg,
  message,
  chatId,
  quoted,
  sendText,
  client,
  context,
  preferNativeButtons,
}: {
  config: SimpleRestCommandConfig;
  arg: string;
  message: NormalizedMessage;
  chatId: string;
  quoted?: { stanzaId: string; participant?: string };
  sendText: (text: string) => Promise<void>;
  client: WuzapiClient;
  context: BotEventContext;
  preferNativeButtons?: boolean;
}): Promise<boolean> => {
  let link = (arg || "").trim();
  if (!link && message.raw) {
    link = findLinkForPlatformFromRaw(message.raw as Record<string, unknown>, config.platform) ?? "";
  }
  if (!link) {
    await sendText(`Use: /${config.names[0]} <url>`);
    return true;
  }
  if (config.platform !== "twitterspaces" && !isSupportedAutoDownloadLink(link, config.platform)) {
    await sendText(`Envie um link válido do ${config.label}.`);
    return true;
  }
  try {
    const apiKey = await getUserRestApiKey(context.instance.userId);
    if (!apiKey) {
      await sendText("⚠️ Gere sua chave da API REST no painel para usar este comando.");
      return true;
    }
    let result: any;
    try {
      result = await fetchGenericRestDownload(config.endpoint, link, { apiKey });
    } catch (error) {
      if (config.endpoint === "/api/download/instagramv2") {
        result = await fetchRestInstagramInflactDownload(link, { apiKey });
      } else {
        throw error;
      }
    }
    const captionParts: string[] = [];
    if (result.title) {
      captionParts.push(config.mediaType === "audio" ? `🎵 ${result.title}` : `🎬 ${result.title}`);
    }
    if (result.author) {
      captionParts.push(`👤 ${result.author}`);
    }
    const caption = captionParts.join("\n") || undefined;
    const mimeType =
      typeof result.format === "string" && result.format.trim()
        ? result.format
        : config.mediaType === "audio"
        ? "audio/mpeg"
        : "video/mp4";
    const extension = (() => {
      if (mimeType.includes("webm")) return "webm";
      if (mimeType.includes("mp4")) return config.mediaType === "audio" ? "m4a" : "mp4";
      return config.mediaType === "audio" ? "mp3" : "mp4";
    })();
    const safeTitle =
      (result.title || config.label).replace(/[^\w\s.-]+/g, "").replace(/\s+/g, "_") ||
      config.label.toLowerCase();
    const affiliateUrl =
      typeof result.affiliateUrl === "string" ? result.affiliateUrl.trim() : "";
    const messageBody =
      (typeof result.messageBody === "string" && result.messageBody.trim()) ||
      caption ||
      "";
    const captionWithAffiliate =
      (typeof result.captionWithAffiliate === "string" && result.captionWithAffiliate.trim()) ||
      (affiliateUrl ? [messageBody, `🔗 ${affiliateUrl}`].filter(Boolean).join("\n\n") : messageBody) ||
      undefined;
    const fileName = `${safeTitle}_${Date.now()}.${extension}`;

    const shouldUseVideoHeaderCta =
      Boolean(preferNativeButtons) &&
      Boolean(affiliateUrl) &&
      Boolean(result.useVideoHeaderCta) &&
      config.mediaType === "video";

    if (shouldUseVideoHeaderCta) {
      try {
        await sendInteractiveButtons(client, {
          to: chatId,
          title:
            (typeof result.affiliateTitle === "string" && result.affiliateTitle.trim()) ||
            config.label,
          body: messageBody || `🔗 ${affiliateUrl}`,
          footer: "Toque no botao para abrir o produto.",
          quoted,
          buttonType: "native",
          headerMedia: {
            type: "video",
            media: result.url,
            mimeType,
            fileName,
          },
          buttons: [
            {
              id: `simple_rest_cta_${Date.now()}`,
              text:
                (typeof result.affiliateButtonText === "string" && result.affiliateButtonText.trim()) ||
                "Ver produto",
              type: "cta_url",
              url: affiliateUrl,
            },
          ],
        });
        return true;
      } catch (ctaError) {
        console.warn("[bot-events] simple rest CTA video header failed", {
          ctaError,
          config: config.names[0],
          affiliateUrl,
        });
      }
    }

    await sendMediaMessage(client, {
      to: chatId,
      media: result.url,
      mediaType: config.mediaType === "audio" ? "audio" : "video",
      filename: fileName,
      mimeType,
      caption: captionWithAffiliate || caption,
      quoted,
    });

    if (affiliateUrl) {
      const ctaTitle =
        (typeof result.affiliateTitle === "string" && result.affiliateTitle.trim()) ||
        (typeof result.title === "string" && result.title.trim()) ||
        config.label;
      const ctaBody =
        (typeof result.affiliateBody === "string" && result.affiliateBody.trim()) ||
        messageBody ||
        `🔗 ${affiliateUrl}`;
      const ctaButtonText =
        (typeof result.affiliateButtonText === "string" && result.affiliateButtonText.trim()) ||
        "Ver produto";
      const ctaImageUrl =
        (typeof result.affiliateImageUrl === "string" && result.affiliateImageUrl.trim()) ||
        (typeof result.thumbnail === "string" && result.thumbnail.trim()) ||
        null;

      if (preferNativeButtons && !shouldUseVideoHeaderCta) {
        try {
          await sendInteractiveButtons(client, {
            to: chatId,
            title: ctaTitle,
            body: ctaBody,
            footer: "Toque no botao para abrir o produto.",
            quoted,
            buttonType: "native",
            headerMedia: ctaImageUrl
              ? {
                  type: "image",
                  media: ctaImageUrl,
                  mimeType: "image/jpeg",
                }
              : null,
            buttons: [
              {
                id: `simple_rest_cta_${Date.now()}`,
                text: ctaButtonText,
                type: "cta_url",
                url: affiliateUrl,
              },
            ],
          });
          return true;
        } catch (ctaError) {
          console.warn("[bot-events] simple rest CTA button failed", {
            ctaError,
            config: config.names[0],
            affiliateUrl,
          });
        }
      }

      await sendTextMessage(client, {
        to: chatId,
        body: [ctaBody, `🔗 ${affiliateUrl}`].filter(Boolean).join("\n\n"),
        quoted,
      });
    }
  } catch (error) {
    console.error("[bot-events] simple rest command error", { error, config: config.names[0], link });
    await sendText(`Falha ao baixar do ${config.label}.`);
  }
  return true;
};

const TARGET_SELECTION_HINT =
  "Use este comando respondendo a uma mensagem, mencionando participantes ou informando o número (ex.: /ban @usuario ou /ban 5511999999999).";

const MANUAL_INFRA_SELECTION_HINT =
  "Use este comando respondendo a uma mensagem, mencionando participantes ou informando o número (ex.: /adv @usuario ou /adv 5511999999999).";

const RESET_INFRA_SELECTION_HINT =
  "Use este comando respondendo a uma mensagem, mencionando participantes ou informando o número (ex.: /res @usuario ou /res 5511999999999).";

const truncateText = (value: string, maxLength = 1000): string =>
  value.length > maxLength ? `${value.slice(0, maxLength)}…` : value;

const formatIntegrationResult = (value: unknown): string | null => {
  if (value === null || value === undefined) {
    return null;
  }

  if (typeof value === "string") {
    return value.trim() ? value : null;
  }

  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  if (typeof Buffer !== "undefined" && Buffer.isBuffer(value)) {
    return `Arquivo gerado (${value.length} bytes)`;
  }

  if (Array.isArray(value)) {
    if (value.length === 0) {
      return "Nenhum item retornado.";
    }
    const sample = value.slice(0, 5);
    const lines = sample.map((entry, index) => {
      if (typeof entry === "string" || typeof entry === "number" || typeof entry === "boolean") {
        return `• ${entry}`;
      }
      if (entry && typeof entry === "object") {
        const entries = Object.entries(entry as Record<string, unknown>)
          .filter(([, v]) => v !== null && v !== undefined)
          .slice(0, 4)
          .map(([key, v]) => `${key}: ${typeof v === "string" ? truncateText(v, 80) : typeof v === "number" || typeof v === "boolean" ? String(v) : Array.isArray(v) ? `${v.length} itens` : "objeto"}`);
        return entries.length ? `• ${entries.join(" | ")}` : `• item ${index + 1}`;
      }
      return `• item ${index + 1}`;
    });
    if (value.length > sample.length) {
      lines.push(`(+${value.length - sample.length} itens)`);
    }
    return lines.join("\n");
  }

  if (typeof value === "object") {
    const record = value as Record<string, unknown>;
    if (typeof record.mensagem === "string" && record.mensagem.trim()) {
      return record.mensagem;
    }
    if (typeof record.message === "string" && record.message.trim()) {
      return record.message;
    }
    if (record.resultado !== undefined) {
      const nested = formatIntegrationResult(record.resultado);
      if (nested) return nested;
    }
    if (record.result !== undefined) {
      const nested = formatIntegrationResult(record.result);
      if (nested) return nested;
    }
    if (record.data !== undefined) {
      const nested = formatIntegrationResult(record.data);
      if (nested) return nested;
    }
    const summary = Object.entries(record)
      .filter(([, v]) => v !== null && v !== undefined)
      .slice(0, 6)
      .map(([key, v]) => {
        if (typeof v === "string") {
          return `${key}: ${truncateText(v, 120)}`;
        }
        if (typeof v === "number" || typeof v === "boolean") {
          return `${key}: ${v}`;
        }
        if (Array.isArray(v)) {
          return `${key}: ${v.length} itens`;
        }
        if (v && typeof v === "object") {
          const nestedKeys = Object.keys(v as Record<string, unknown>).slice(0, 3).join(", ");
          return `${key}: { ${nestedKeys || "objeto"} }`;
        }
        return `${key}: ${String(v)}`;
      });
    if (summary.length) {
      return summary.join("\n");
    }
    try {
      return truncateText(JSON.stringify(record, null, 2));
    } catch {
      return "Comando executado sem resposta textual.";
    }
  }

  return null;
};

const randomIntInclusive = (min: number, max: number) =>
  Math.floor(Math.random() * (max - min + 1)) + min;

const fetchRandomPensadorQuote = async (temaRaw: string): Promise<PensadorQuote> => {
  const tema = (temaRaw || DEFAULT_PENSADOR_TOPIC).trim() || DEFAULT_PENSADOR_TOPIC;
  let lastError: unknown = null;
  for (let attempt = 0; attempt < 5; attempt += 1) {
    const page =
      attempt === 0 ? 1 : randomIntInclusive(1, MAX_PENSADOR_PAGE);
    try {
      const data = await fetchPensadorQuotes({
        tema,
        page,
        limit: MAX_PENSADOR_LIMIT,
      });
      if (data.quotes.length) {
        return data.quotes[randomIntInclusive(0, data.quotes.length - 1)];
      }
    } catch (error) {
      lastError = error;
    }
  }
  throw (lastError as Error) ?? new Error("Não foi possível obter uma frase no momento.");
};

const buildAvatarResolver = (
  client: WuzapiClient,
  message: NormalizedMessage,
  senderDigits: string,
) => {
  let cachedAvatar: UserAvatarResult | null | undefined;
  return async (): Promise<UserAvatarResult | null> => {
    if (cachedAvatar !== undefined) {
      return cachedAvatar;
    }
    cachedAvatar = null;
    const avatarTarget =
      message.senderJid ??
      message.participant ??
      (senderDigits ? `${senderDigits}` : null);
    if (!avatarTarget) {
      return cachedAvatar;
    }
    try {
      cachedAvatar = await getUserAvatar(client, {
        contact: avatarTarget,
        preview: true,
      });
    } catch (error) {
      console.warn("[bot-events] avatar fetch failed", { error });
      cachedAvatar = null;
    }
    return cachedAvatar;
  };
};

type SiteIntegrationSettings = {
  baseUrl: string;
  apiKey: string;
};

const ENABLE_CARD_REMOTE = process.env.ENABLE_CARD_REMOTE === "true";
const REMOTE_CARD_SUSPEND_MS = 1000 * 60 * 60;
const REMOTE_CARD_RETRY_MS = 1000 * 60 * 5;
let cardRemoteSuspendedUntil = 0;

const getSiteIntegrationSettings = (() => {
  let cached: SiteIntegrationSettings | null = null;
  return (): SiteIntegrationSettings => {
    if (cached) return cached;

    let baseUrl = getAppBaseUrl().replace(/\/+$/, "");
    let apiKey = process.env.SITE_API_KEY?.trim() || "equipevipadm";

    try {
      const cfg = (eval("require") as NodeRequire)("config/app-settings.js");
      if (typeof cfg?.basesiteUrl === "string" && cfg.basesiteUrl.trim()) {
        baseUrl = cfg.basesiteUrl.trim().replace(/\/+$/, "");
      }
      if (typeof cfg?.apikeypremium === "string" && cfg.apikeypremium.trim()) {
        apiKey = cfg.apikeypremium.trim();
      }
    } catch {
      /* ignore */
    }

    cached = { baseUrl, apiKey };
    return cached;
  };
})();

type StickerMediaSource = {
  kind: "url" | "data" | "meta";
  value: string;
  mimeType?: string | null;
  meta?: Record<string, unknown>;
};

const isTruthyMediaFlag = (value: unknown): boolean =>
  value === true || (typeof value === "string" && /^(1|true|yes|sim)$/i.test(value.trim()));

const isGifMediaDescriptor = (
  mimeType?: string | null,
  fileName?: string | null,
  mediaType?: string | null,
): boolean => {
  const normalizedMime = String(mimeType ?? "").trim().toLowerCase();
  const normalizedName = String(fileName ?? "").trim().toLowerCase();
  const normalizedType = String(mediaType ?? "").trim().toLowerCase();
  return (
    normalizedMime === "image/gif" ||
    normalizedType.includes("gif") ||
    /\.gif(?:$|[?#])/.test(normalizedName)
  );
};

const isAnimatedGifStickerSource = (source: StickerMediaSource | null | undefined): boolean => {
  if (!source) {
    return false;
  }
  const meta = toRecord(source.meta ?? {});
  return (
    isGifMediaDescriptor(
      firstString(meta.mimetype, meta.Mimetype, meta.mimeType, meta.MimeType, source.mimeType),
      firstString(meta.fileName, meta.FileName, meta.filename, meta.Filename),
      firstString(meta.NodeType, meta.nodeType, meta.type, meta.mediaType, meta.MediaType),
    ) ||
    isTruthyMediaFlag(meta.gifPlayback) ||
    isTruthyMediaFlag(meta.GifPlayback) ||
    isTruthyMediaFlag(meta.isGif) ||
    isTruthyMediaFlag(meta.IsGif)
  );
};

// Extrai uma fonte de mídia apropriada para conversão em figurinha a partir do payload bruto
const extractStickerSourceFromMessage = (
  message: NormalizedMessage,
  options?: { roots?: Record<string, unknown>[]; includeQuoted?: boolean; allowAnyDocument?: boolean },
): StickerMediaSource | null => {
  // 1) Tenta encontrar uma URL direta de mídia (imageMessage/VIDEO)
  // Retorna também o próprio nó da mídia encontrado para extrair metadados corretos (directPath/mediaKey/...)
  const includeQuoted = options?.includeQuoted !== false;
  const allowAnyDocument = options?.allowAnyDocument === true;

  const tryFindMediaUrl = (
    obj: unknown,
  ): { url: string; mimeType?: string | null; node?: Record<string, unknown>; nodeType?: 'image' | 'video' | 'audio' | 'document' | 'sticker' } | null => {
    const stack: Array<{ node: unknown; skip: boolean }> = [{ node: obj, skip: false }];
    const seen = new Set<unknown>();
    const shouldSkipKey = (key: string) =>
      !includeQuoted &&
      typeof key === "string" &&
      key.toLowerCase().includes("quoted");

    while (stack.length) {
      const current = stack.pop();
      if (!current) continue;
      const { node, skip } = current;
      if (!node || typeof node !== "object") continue;
      if (seen.has(node)) continue;
      seen.add(node);
      if (skip) {
        continue;
      }
      const cur = node as Record<string, unknown>;
      const buildDirectUrl = (directPath: string): string =>
        directPath.startsWith("http")
          ? directPath
          : `https://mmg.whatsapp.net${directPath.startsWith("/") ? "" : "/"}${directPath}`;
      const resolveMediaNode = (
        primaryKey: string,
        fallbackKey: string,
        nodeType: "image" | "video" | "audio" | "document" | "sticker",
        defaultMime: string,
      ): { url: string; mimeType?: string | null; node?: Record<string, unknown>; nodeType?: "image" | "video" | "audio" | "document" | "sticker" } | null => {
        const rawNode = cur[primaryKey] ?? cur[fallbackKey];
        if (!rawNode || typeof rawNode !== "object") {
          return null;
        }
        const mediaNode = toRecord(rawNode);
        const url = firstString(mediaNode.URL, mediaNode.Url, mediaNode.url, mediaNode.mediaUrl, mediaNode.mediaURL);
        const directPath = firstString(
          mediaNode.directPath,
          mediaNode.DirectPath,
          mediaNode.directpath,
          mediaNode.direct_path,
          mediaNode.Direct_Path,
        );
        const fileName = firstString(
          mediaNode.fileName,
          mediaNode.FileName,
          mediaNode.filename,
          mediaNode.Filename,
        );
        const mimeType =
          firstString(mediaNode.mimetype, mediaNode.Mimetype, defaultMime) ?? defaultMime;

        if (nodeType === "document") {
          const inferred = inferMediaGuardKindFromMimeOrName(mimeType, fileName);
          const looksLikeMedia =
            inferred === "image" || inferred === "video" || inferred === "audio" || inferred === "sticker";
          if (!looksLikeMedia && !allowAnyDocument) {
            return null;
          }
        }

        if (url) {
          return { url, mimeType, node: mediaNode, nodeType };
        }
        if (directPath) {
          return { url: buildDirectUrl(directPath), mimeType, node: mediaNode, nodeType };
        }
        return null;
      };
      const resolveMediaDescriptor = (
        rawNode: unknown,
      ): { url: string; mimeType?: string | null; node?: Record<string, unknown>; nodeType?: "image" | "video" | "audio" | "document" | "sticker" } | null => {
        if (!rawNode || typeof rawNode !== "object") {
          return null;
        }
        const mediaNode = toRecord(rawNode);
        const rawType = (firstString(mediaNode.type, mediaNode.Type, mediaNode.mediaType, mediaNode.MediaType) ?? "").toLowerCase();
        const mimeType = firstString(
          mediaNode.mimetype,
          mediaNode.Mimetype,
          mediaNode.mimeType,
          mediaNode.MimeType,
          mediaNode.contentType,
          mediaNode.ContentType,
        );
        const fileName = firstString(mediaNode.fileName, mediaNode.FileName, mediaNode.filename, mediaNode.Filename, mediaNode.name);
        const url = firstString(mediaNode.url, mediaNode.URL, mediaNode.Url, mediaNode.mediaUrl, mediaNode.mediaURL);
        const directPath = firstString(
          mediaNode.directPath,
          mediaNode.DirectPath,
          mediaNode.directpath,
          mediaNode.direct_path,
          mediaNode.Direct_Path,
        );
        const inferred = inferMediaGuardKindFromMimeOrName(mimeType, fileName);
        const looksLikeDirectDocument =
          allowAnyDocument &&
          Boolean(mimeType || fileName || directPath || firstString(mediaNode.mediaKey, mediaNode.MediaKey));
        const nodeType =
          rawType === "image" || rawType === "video" || rawType === "audio" || rawType === "document" || rawType === "sticker"
            ? rawType
            : inferred === "image" || inferred === "video" || inferred === "audio" || inferred === "sticker"
              ? inferred
              : looksLikeDirectDocument
                ? "document"
              : null;
        if (!nodeType) {
          return null;
        }
        if (url) {
          return { url, mimeType, node: mediaNode, nodeType };
        }
        if (directPath) {
          return { url: buildDirectUrl(directPath), mimeType, node: mediaNode, nodeType };
        }
        return null;
      };

      const candidate =
        resolveMediaNode("imageMessage", "image", "image", "image/jpeg") ??
        resolveMediaNode("videoMessage", "video", "video", "video/mp4") ??
        resolveMediaNode("audioMessage", "audio", "audio", "audio/ogg") ??
        resolveMediaNode("stickerMessage", "sticker", "sticker", "image/webp") ??
        resolveMediaNode("documentMessage", "document", "document", "application/octet-stream") ??
        resolveMediaDescriptor(cur.Media ?? cur.media) ??
        resolveMediaDescriptor(cur);
      if (candidate) {
        return candidate;
      }
      for (const [key, value] of Object.entries(cur)) {
        if (value && typeof value === "object") {
          stack.push({ node: value, skip: shouldSkipKey(key) });
        }
      }
    }
    return null;
  };

  // 2) Tenta encontrar uma miniatura base64 (JPEGThumbnail) em qualquer ponto do payload
  const tryFindBase64 = (obj: unknown): { dataUri: string; mimeType?: string | null } | null => {
    const stack: Array<{ node: unknown; skip: boolean }> = [{ node: obj, skip: false }];
    const seen = new Set<unknown>();
    const shouldSkipKey = (key: string) =>
      !includeQuoted &&
      typeof key === "string" &&
      key.toLowerCase().includes("quoted");

    while (stack.length) {
      const current = stack.pop();
      if (!current) continue;
      const { node, skip } = current;
      if (!node || typeof node !== "object") continue;
      if (seen.has(node)) continue;
      seen.add(node);
      if (skip) {
        continue;
      }
      const cur = node as Record<string, unknown>;
      const resolveThumbFromNode = (
        rawNode: unknown,
        fallbackMime: string,
      ): { dataUri: string; mimeType?: string | null } | null => {
	        if (!rawNode || typeof rawNode !== "object") {
	          return null;
	        }
	        const mediaNode = toRecord(rawNode);
	        const sourceMime = firstString(
	          mediaNode.mimetype,
	          mediaNode.Mimetype,
	          mediaNode.mimeType,
	          mediaNode.MimeType,
	        );
	        const sourceName = firstString(mediaNode.fileName, mediaNode.FileName, mediaNode.filename, mediaNode.Filename);
	        const sourceType = firstString(mediaNode.type, mediaNode.Type, mediaNode.mediaType, mediaNode.MediaType);
	        if (
	          isGifMediaDescriptor(sourceMime, sourceName, sourceType) ||
	          isTruthyMediaFlag(mediaNode.gifPlayback) ||
	          isTruthyMediaFlag(mediaNode.GifPlayback)
	        ) {
	          return null;
	        }
	        const thumb = firstString(
	          mediaNode.JPEGThumbnail,
	          mediaNode.jpegThumbnail,
	          mediaNode.PNGThumbnail,
	          mediaNode.pngThumbnail,
          mediaNode.thumbnail,
          mediaNode.Thumbnail,
        );
        if (!thumb) {
          return null;
        }
        if (/^data:/i.test(thumb)) {
          return { dataUri: thumb, mimeType: firstString(mediaNode.mimetype, mediaNode.Mimetype) };
        }

	        const mimeType =
	          firstString(
	            typeof mediaNode.PNGThumbnail === "string" || typeof mediaNode.pngThumbnail === "string" ? "image/png" : null,
	            "image/jpeg",
	            fallbackMime,
	          ) ?? fallbackMime;
	        return { dataUri: `data:${mimeType};base64,${thumb}`, mimeType };
	      };

      const imageThumb =
        resolveThumbFromNode(cur.imageMessage ?? cur.image, "image/jpeg") ??
        resolveThumbFromNode(cur.stickerMessage ?? cur.sticker, "image/png") ??
        resolveThumbFromNode(cur.videoMessage ?? cur.video, "image/jpeg");
      if (imageThumb) {
        return imageThumb;
      }

      const rawDocumentNode = cur.documentMessage ?? cur.document;
      if (rawDocumentNode && typeof rawDocumentNode === "object") {
        const doc = toRecord(rawDocumentNode);
        const docMime = firstString(doc.mimetype, doc.Mimetype, "application/octet-stream");
        const docName = firstString(doc.fileName, doc.FileName, doc.filename, doc.Filename);
        const inferred = inferMediaGuardKindFromMimeOrName(docMime, docName);
        if (inferred === "image" || inferred === "video" || inferred === "audio" || inferred === "sticker") {
          const docThumb = resolveThumbFromNode(doc, "image/jpeg");
          if (docThumb) {
            return docThumb;
          }
        }
      }
      for (const [key, value] of Object.entries(cur)) {
        if (value && typeof value === "object") {
          stack.push({ node: value, skip: shouldSkipKey(key) });
        }
      }
    }
    return null;
  };

  const resolveRoots = (): Record<string, unknown>[] => {
    if (options?.roots?.length) {
      const normalized = options.roots.map((entry) => toRecord(entry)).filter((entry) => Object.keys(entry).length > 0);
      if (normalized.length > 0) {
        return normalized;
      }
    }
    const fallback = toRecord(message.raw);
    return Object.keys(fallback).length > 0 ? [fallback] : [];
  };

  const searchRoots = resolveRoots();

  for (const root of searchRoots) {
    const media = tryFindMediaUrl(root);
    if (media && media.url) {
    // Extrai metadados do próprio nó da mídia encontrado (inclui quotedMessage, etc.)
    const node = toRecord(media.node ?? {});
    const meta: Record<string, unknown> = {};
    const pickFirst = (targetKey: string, ...keys: string[]) => {
      for (const key of keys) {
        const value = node[key];
        if (value !== undefined && value !== null && String(value).trim() !== "") {
          meta[targetKey] = value;
          return;
        }
      }
    };
    pickFirst("directPath", "directPath", "DirectPath", "directpath", "direct_path", "Direct_Path");
    pickFirst("mediaKey", "mediaKey", "MediaKey", "media_key", "Media_Key");
    pickFirst("fileEncSHA256", "fileEncSHA256", "FileEncSHA256", "fileEncSha256", "FileEncSha256", "file_enc_sha256", "FileEncSHA256");
    pickFirst("fileSHA256", "fileSHA256", "FileSHA256", "fileSha256", "FileSha256", "file_sha256");
	    pickFirst("mimetype", "mimetype", "Mimetype", "mimeType", "MimeType", "contentType", "ContentType");
	    pickFirst("fileLength", "fileLength", "FileLength", "file_length", "size", "Size");
	    pickFirst("fileName", "fileName", "FileName", "filename", "Filename", "name");
	    pickFirst("gifPlayback", "gifPlayback", "GifPlayback", "gif_playback", "isGif", "IsGif");
	    if (media.nodeType) meta.NodeType = media.nodeType;

    const isMmg = typeof media.url === "string" && /(^|\.)mmg\.whatsapp\.net/i.test(media.url);
    if (Object.keys(meta).length || isMmg) {
      return { kind: "meta", value: media.url, mimeType: media.mimeType, meta };
    }
    return { kind: "url", value: media.url, mimeType: media.mimeType };
    }
  }
  for (const root of searchRoots) {
    const dataObj = tryFindBase64(root);
    if (dataObj) return { kind: "data", value: dataObj.dataUri, mimeType: dataObj.mimeType };
  }
  return null;
};

const resolveStickerSourceFromMessageOrQuote = async (
  client: WuzapiClient,
  message: NormalizedMessage,
  options: { allowAnyDocument?: boolean } = {},
): Promise<StickerMediaSource | null> => {
  const direct = extractStickerSourceFromMessage(message, {
    includeQuoted: false,
    allowAnyDocument: options.allowAnyDocument === true,
  });
  if (direct) {
    return direct;
  }
  if (!message.chatId) {
    return null;
  }

  if (message.id) {
    const selfSenderCandidates = Array.from(
      new Set(
        [
          message.senderJid,
          message.participant,
          null,
        ].filter((value): value is string | null => value === null || (typeof value === "string" && value.trim().length > 0)),
      ),
    );

    for (const sender of selfSenderCandidates) {
      try {
        const current = await getChatMessage(client, {
          chatId: message.chatId,
          messageId: message.id,
          sender,
        });
        if (!current) {
          continue;
        }
        const roots = [
          toRecord(current),
          toRecord(current.Message),
          toRecord(current.Media),
          { Message: current.Message, Media: current.Media },
          { message: current.Message, media: current.Media },
        ].filter((root) => Object.keys(toRecord(root)).length > 0);
        const source = extractStickerSourceFromMessage(message, {
          roots,
          includeQuoted: false,
          allowAnyDocument: options.allowAnyDocument === true,
        });
        if (source) {
          return source;
        }
      } catch (error) {
        console.warn("[bot-events] falha ao buscar mídia da própria mensagem pela API", {
          chatId: message.chatId,
          messageId: message.id,
          sender,
          error,
        });
      }
    }
  }

  if (!message.quotedMessageId) {
    return null;
  }

  const senderCandidates = Array.from(
    new Set(
      [
        message.quotedParticipant,
        message.senderJid,
        message.participant,
        null,
      ].filter((value): value is string | null => value === null || (typeof value === "string" && value.trim().length > 0)),
    ),
  );

  for (const sender of senderCandidates) {
    try {
      const quoted = await getChatMessage(client, {
        chatId: message.chatId,
        messageId: message.quotedMessageId,
        sender,
      });
      if (!quoted) {
        continue;
      }
      const roots = [
        toRecord(quoted),
        toRecord(quoted.Message),
        toRecord(quoted.Media),
        { Message: quoted.Message, Media: quoted.Media },
        { message: quoted.Message, media: quoted.Media },
      ].filter((root) => Object.keys(toRecord(root)).length > 0);
      const source = extractStickerSourceFromMessage(message, {
        roots,
        includeQuoted: false,
        allowAnyDocument: options.allowAnyDocument === true,
      });
      if (source) {
        return source;
      }
    } catch (error) {
      console.warn("[bot-events] falha ao buscar mídia citada pela API", {
        chatId: message.chatId,
        quotedMessageId: message.quotedMessageId,
        sender,
        error,
      });
    }
  }

  return null;
};

const buildAudioCloneCacheKey = (chatId: string | null | undefined, messageId: string | null | undefined): string | null => {
  const chat = (chatId || "").trim();
  const id = (messageId || "").trim();
  return chat && id ? `${chat}:${id}` : null;
};

const buildAudioCloneLatestCacheKeys = (
  chatId: string | null | undefined,
  participants: Array<string | null | undefined>,
): string[] => {
  const chat = (chatId || "").trim();
  if (!chat) return [];

  const normalizedChat = normalizeJid(chat) || chat;
  const keys = new Set<string>();
  for (const participant of participants) {
    const raw = (participant || "").trim();
    const normalized = normalizeJid(raw);
    const actor = normalized || raw;
    if (!actor || actor === normalizedChat || raw === chat) {
      continue;
    }
    keys.add(`${chat}:${actor}`);
  }
  return [...keys];
};

const pruneAudioCloneMessageCache = (now = Date.now()): void => {
  for (const [key, entry] of audioCloneMessageCache.entries()) {
    if (now - entry.createdAt > AUDIO_CLONE_MESSAGE_CACHE_TTL_MS) {
      audioCloneMessageCache.delete(key);
    }
  }
  for (const [key, entry] of audioCloneLatestMessageByChatSender.entries()) {
    if (now - entry.createdAt > AUDIO_CLONE_MESSAGE_CACHE_TTL_MS) {
      audioCloneLatestMessageByChatSender.delete(key);
    }
  }
  while (audioCloneMessageCache.size > AUDIO_CLONE_MESSAGE_CACHE_LIMIT) {
    const firstKey = audioCloneMessageCache.keys().next().value;
    if (!firstKey) break;
    audioCloneMessageCache.delete(firstKey);
  }
  while (audioCloneLatestMessageByChatSender.size > AUDIO_CLONE_MESSAGE_CACHE_LIMIT) {
    const firstKey = audioCloneLatestMessageByChatSender.keys().next().value;
    if (!firstKey) break;
    audioCloneLatestMessageByChatSender.delete(firstKey);
  }
};

const isLikelyValidAudioBuffer = (buffer: Buffer | null | undefined): boolean => {
  if (!buffer || buffer.length < MIN_VOICE_CLONE_AUDIO_BYTES) {
    return false;
  }
  const head = buffer.subarray(0, 16);
  const ascii = head.toString("latin1");
  return (
    ascii.startsWith("ID3") ||
    ascii.startsWith("OggS") ||
    ascii.startsWith("RIFF") ||
    ascii.startsWith("fLaC") ||
    ascii.includes("ftyp") ||
    buffer[0] === 0xff
  );
};

const normalizeWhatsAppMediaByteField = (value: unknown): string | undefined => {
  if (typeof value === "string" && value.trim()) {
    return value.trim();
  }
  if (Buffer.isBuffer(value)) {
    return value.length > 0 ? value.toString("base64") : undefined;
  }
  if (value instanceof Uint8Array) {
    return value.length > 0 ? Buffer.from(value).toString("base64") : undefined;
  }
  if (Array.isArray(value) && value.every((entry) => Number.isInteger(entry) && entry >= 0 && entry <= 255)) {
    return value.length > 0 ? Buffer.from(value as number[]).toString("base64") : undefined;
  }
  const record = toRecord(value);
  const data = record.data ?? record.Data;
  if (Array.isArray(data) && data.every((entry) => Number.isInteger(entry) && entry >= 0 && entry <= 255)) {
    return data.length > 0 ? Buffer.from(data as number[]).toString("base64") : undefined;
  }
  return undefined;
};

const firstMediaByteString = (...values: unknown[]): string | undefined => {
  for (const value of values) {
    const normalized = normalizeWhatsAppMediaByteField(value);
    if (normalized) {
      return normalized;
    }
  }
  return undefined;
};

const rememberAudioCloneMessage = (message: NormalizedMessage): void => {
  const key = buildAudioCloneCacheKey(message.chatId, message.id);
  if (!key) {
    return;
  }
  const mediaKind = detectMediaGuardKind(message);
  if (mediaKind !== "audio" && mediaKind !== "video") {
    const source = extractStickerSourceFromMessage(message, { includeQuoted: false });
    const meta = toRecord(source?.meta ?? {});
    const kind =
      ((firstString(meta.NodeType, meta.nodeType, meta.type) ?? "").toLowerCase() as MediaGuardKind | "") ||
      inferMediaGuardKindFromMimeOrName(firstString(meta.mimetype, meta.Mimetype, source?.mimeType), firstString(meta.fileName, meta.FileName));
    if (kind !== "audio" && kind !== "video") {
      return;
    }
  }
  const now = Date.now();
  pruneAudioCloneMessageCache(now);
  const entry = { raw: message.raw, createdAt: now };
  audioCloneMessageCache.set(key, entry);
  for (const latestKey of buildAudioCloneLatestCacheKeys(message.chatId, [
    message.participant,
    message.senderJid,
  ])) {
    audioCloneLatestMessageByChatSender.set(latestKey, entry);
  }
};

// Busca uma miniatura (JPEGThumbnail) no payload bruto e retorna um Data URI utilizável como fallback
const findThumbnailDataUriFromRaw = (raw: Record<string, unknown>): string | null => {
  const stack: any[] = [raw];
  const seen = new Set<any>();
  while (stack.length) {
    const cur = stack.pop();
    if (!cur || typeof cur !== 'object') continue;
    if (seen.has(cur)) continue;
    seen.add(cur);
    const rec = toRecord(cur);
    if (rec.imageMessage && typeof rec.imageMessage === 'object') {
      const img = toRecord(rec.imageMessage);
      const b64 = typeof img.JPEGThumbnail === 'string' ? img.JPEGThumbnail.trim() : '';
      const mt = typeof img.mimetype === 'string' && img.mimetype.trim() ? String(img.mimetype).trim() : 'image/jpeg';
      if (b64) return `data:${mt};base64,${b64}`;
    }
    if (rec.videoMessage && typeof rec.videoMessage === "object") {
      const video = toRecord(rec.videoMessage);
      const b64 =
        (typeof video.JPEGThumbnail === "string" && video.JPEGThumbnail.trim()) ||
        (typeof video.thumbnail === "string" && video.thumbnail.trim()) ||
        "";
      if (b64) return `data:image/jpeg;base64,${b64}`;
    }
    if (rec.stickerMessage && typeof rec.stickerMessage === "object") {
      const sticker = toRecord(rec.stickerMessage);
      const pngThumb =
        (typeof sticker.PNGThumbnail === "string" && sticker.PNGThumbnail.trim()) ||
        (typeof sticker.pngThumbnail === "string" && sticker.pngThumbnail.trim()) ||
        "";
      if (pngThumb) return `data:image/png;base64,${pngThumb}`;
      const jpgThumb =
        (typeof sticker.JPEGThumbnail === "string" && sticker.JPEGThumbnail.trim()) ||
        (typeof sticker.jpegThumbnail === "string" && sticker.jpegThumbnail.trim()) ||
        "";
      if (jpgThumb) return `data:image/jpeg;base64,${jpgThumb}`;
    }
    for (const v of Object.values(rec)) {
      if (v && typeof v === 'object') stack.push(v);
    }
  }
  return null;
};

const toRecord = (value: unknown): Record<string, unknown> =>
  value && typeof value === "object" ? (value as Record<string, unknown>) : {};

const firstString = (...candidates: unknown[]): string | null => {
  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim().length > 0) {
      return candidate.trim();
    }
    if (typeof candidate === "number" && Number.isFinite(candidate)) {
      const asString = String(candidate);
      if (asString.trim().length > 0) {
        return asString.trim();
      }
    }
  }
  return null;
};

const firstBoolean = (...candidates: unknown[]): boolean | null => {
  for (const candidate of candidates) {
    if (typeof candidate === "boolean") {
      return candidate;
    }
    if (typeof candidate === "string") {
      const normalized = candidate.trim().toLowerCase();
      if (["true", "1", "yes", "sim"].includes(normalized)) {
        return true;
      }
      if (["false", "0", "no", "nao", "não"].includes(normalized)) {
        return false;
      }
    }
    if (typeof candidate === "number" && Number.isFinite(candidate)) {
      return candidate !== 0;
    }
  }
  return null;
};

const firstNumber = (...candidates: unknown[]): number | null => {
  for (const candidate of candidates) {
    if (typeof candidate === "number" && Number.isFinite(candidate)) {
      return candidate;
    }
    if (typeof candidate === "string") {
      const trimmed = candidate.trim();
      if (!trimmed) {
        continue;
      }
      const parsed = Number(trimmed);
      if (Number.isFinite(parsed)) {
        return parsed;
      }
    }
  }
  return null;
};

const resolveMessageActorDigits = (message: NormalizedMessage): string => {
  const groupDigits = normalizeJid(message.chatId);
  const candidates: string[] = [];
  const pushCandidate = (value: unknown) => {
    if (typeof value === "string" && value.trim()) {
      candidates.push(value.trim());
    } else if (typeof value === "number" && Number.isFinite(value)) {
      candidates.push(String(value));
    }
  };

  pushCandidate(message.participant);
  pushCandidate(message.senderJid);

  const raw = toRecord(message.raw);
  const normalized = toRecord(raw.normalized ?? raw.Normalized);
  const info = toRecord(raw.Info ?? raw.info);
  const keyRecord = toRecord(raw.key ?? {});
  const messageRecord = toRecord(raw.Message ?? raw.message);
  const messageKey = toRecord(messageRecord.key ?? {});
  const messageInfo = toRecord(messageRecord.Info ?? messageRecord.info);
  const nestedMessage = toRecord(messageRecord.message);
  const nestedExtended = toRecord(nestedMessage.extendedTextMessage);
  const rawMessage = toRecord(raw.RawMessage ?? raw.rawMessage);
  const rawMessageKey = toRecord(rawMessage.key ?? {});
  const rawMessageInfo = toRecord(rawMessage.Info ?? rawMessage.info);
  const rawNestedMessage = toRecord(rawMessage.message);
  const rawNestedExtended = toRecord(rawNestedMessage.extendedTextMessage);
  const rawContextCandidates: Array<Record<string, unknown>> = [
    toRecord(raw.contextInfo ?? raw.ContextInfo),
    toRecord(messageRecord.contextInfo ?? messageRecord.ContextInfo),
    toRecord(nestedMessage.contextInfo ?? nestedMessage.ContextInfo),
    toRecord(nestedExtended.contextInfo ?? nestedExtended.ContextInfo),
    toRecord(rawMessage.contextInfo ?? rawMessage.ContextInfo),
    toRecord(rawNestedMessage.contextInfo ?? rawNestedMessage.ContextInfo),
    toRecord(rawNestedExtended.contextInfo ?? rawNestedExtended.ContextInfo),
  ];

  const pushRecordFields = (record: Record<string, unknown>, fields: string[]) => {
    for (const field of fields) {
      if (Object.prototype.hasOwnProperty.call(record, field)) {
        pushCandidate(record[field]);
      }
    }
  };

  pushRecordFields(normalized, [
    "participant",
    "participantJid",
    "participant_jid",
    "participantNormalized",
    "participant_normalized",
    "sender",
    "senderJid",
    "sender_jid",
    "senderNormalized",
    "sender_normalized",
  ]);

  pushRecordFields(info, [
    "Participant",
    "participant",
    "ParticipantNormalized",
    "participantNormalized",
    "Sender",
    "sender",
    "SenderNormalized",
    "senderNormalized",
  ]);

  pushRecordFields(raw, ["participant", "Participant", "sender", "Sender"]);
  pushRecordFields(keyRecord, ["participant", "Participant"]);
  pushRecordFields(messageRecord, ["participant", "Participant", "sender", "Sender"]);
  pushRecordFields(messageKey, ["participant", "Participant", "remoteJid", "RemoteJid"]);
  pushRecordFields(messageInfo, [
    "Participant",
    "participant",
    "ParticipantNormalized",
    "participantNormalized",
    "Sender",
    "sender",
    "SenderNormalized",
    "senderNormalized",
  ]);
  pushRecordFields(nestedMessage, ["participant", "Participant", "sender", "Sender"]);
  pushRecordFields(nestedExtended, ["participant", "Participant", "sender", "Sender"]);
  pushRecordFields(rawMessage, ["participant", "Participant", "sender", "Sender"]);
  pushRecordFields(rawMessageKey, ["participant", "Participant", "remoteJid", "RemoteJid"]);
  pushRecordFields(rawMessageInfo, [
    "Participant",
    "participant",
    "ParticipantNormalized",
    "participantNormalized",
    "Sender",
    "sender",
    "SenderNormalized",
    "senderNormalized",
  ]);
  pushRecordFields(rawNestedMessage, ["participant", "Participant", "sender", "Sender"]);
  pushRecordFields(rawNestedExtended, ["participant", "Participant", "sender", "Sender"]);

  for (const contextRecord of rawContextCandidates) {
    pushRecordFields(contextRecord, [
      "participant",
      "Participant",
      "participantJid",
      "ParticipantJid",
      "participantId",
      "ParticipantId",
      "participantNormalized",
      "ParticipantNormalized",
      "sender",
      "Sender",
    ]);
  }

  const seen = new Set<string>();
  for (const candidate of candidates) {
    if (!candidate || seen.has(candidate)) continue;
    seen.add(candidate);
    if (isGroupJid(candidate)) continue;
    const digits = normalizeJid(candidate);
    if (!digits) continue;
    if (groupDigits && digits === groupDigits) continue;
    if (digits.length < 8) continue;
    return digits;
  }

  return "";
};

