const buildBotAdminNativeMenuLists = (
  kind: NativeMenuKind,
  prefix: string,
  toggles: Partial<BotGroupCommandToggles>,
  defaultButtonText: string,
): ListMessageList[] => {
  if (kind !== "main") {
    const sections = buildBotAdminNativeMenuSections(kind, prefix, toggles);
    return sections.length > 0
      ? [
          {
            buttonText: defaultButtonText,
            sections,
          },
        ]
      : [];
  }

  const mainLists: Array<{ buttonText: string; kind: NativeMenuKind }> = [
    { buttonText: "🧭 Geral", kind: "commands" },
    { buttonText: "🛡️ Admin", kind: "admin" },
  ];

  return mainLists
    .map((entry) => ({
      buttonText: entry.buttonText,
      sections: buildBotAdminNativeMenuSections(entry.kind, prefix, toggles),
    }))
    .filter((entry) => entry.sections.length > 0);
};

