const sendBotAdminNativeMenuList = async (
  client: WuzapiClient,
	  params: {
	    chatId: string;
	    kind: NativeMenuKind;
	    prefix: string;
	    toggles: Partial<BotGroupCommandToggles>;
	    groupName?: string | null;
	    botName?: string | null;
	    imagePath?: string | null;
	    titleOverride?: string | null;
	    descriptionOverride?: string | null;
	    footerOverride?: string | null;
	    menuCarousel?: BotGroupMenuCarousel | null;
	    replacements?: Record<string, string | null | undefined>;
	  },
): Promise<boolean> => {
  const menuKinds: NativeMenuKind[] =
    params.kind === "main"
      ? ["commands", "admin", "downloads", "fun"]
      : [params.kind];
  const cardKindByMenuKind: Record<NativeMenuKind, BotGroupMenuCardKind> = {
    main: "main",
    commands: "main",
    admin: "admin",
    downloads: "downloads",
    fun: "fun",
  };
  const configuredCards = new Map(
    (params.menuCarousel?.cards ?? []).map((card) => [card.kind, card]),
  );
  const renderOverride = (value: string | null | undefined) => {
    const normalized = value?.trim();
    return normalized
      ? applyMenuPlaceholders(normalized, params.replacements ?? {})
      : null;
  };
  const cardMediaCache = new Map<
    string,
    Promise<ListMessageMedia | null>
  >();
  const loadCardMedia = async (
    imagePath: string | null | undefined,
    cardKind: BotGroupMenuCardKind,
  ): Promise<ListMessageMedia | null> => {
    const cacheKey = imagePath?.trim() || "__without_media__";
    const cached = cardMediaCache.get(cacheKey);
    if (cached) return cached;

    const task = (async (): Promise<ListMessageMedia | null> => {
      try {
        const resource = await loadMenuImageResource(imagePath ?? null);
        if (!resource) return null;
        return resource.kind === "url"
          ? { type: "image", media: resource.url }
          : {
              type: "image",
              media: resource.buffer,
              mimeType: resource.mimeType ?? undefined,
              fileName: resource.filename ?? undefined,
            };
      } catch (error) {
        console.error("[bot-events] Falha ao preparar mídia do card do menu", {
          chatId: params.chatId,
          cardKind,
          error,
        });
        return null;
      }
    })();
    cardMediaCache.set(cacheKey, task);
    return task;
  };
  const officialGroupUrl = await (async () => {
    try {
      const site = await getAdminSiteSettings();
      const activeGroup = site.officialGroups?.find(
        (group) => group.isActive && group.inviteLink?.trim(),
      );
      return (
        activeGroup?.inviteLink?.trim() ||
        site.officialGroupInviteLink?.trim() ||
        null
      );
    } catch (error) {
      console.warn("[bot-events] Falha ao resolver link do grupo oficial no menu", error);
      return null;
    }
  })();
  const siteUrl = getPublicAppBaseUrl().replace(/\/+$/, "");
  const resolveCommandPayload = (value: string): string => {
    const rendered = renderOverride(value) ?? value.trim();
    if (!rendered) return "";
    return /^[!/#.]/.test(rendered)
      ? rendered
      : `${params.prefix}${rendered.replace(/^[!/#.]+/, "")}`;
  };
  const buildConfiguredSections = (
    configured: BotGroupMenuCarousel["cards"][number] | undefined,
    menuKind: NativeMenuKind,
  ): ListMessageSection[] => {
    if (configured?.sections === null || configured?.sections === undefined) {
      return buildBotAdminNativeMenuSections(
        menuKind,
        params.prefix,
        params.toggles,
      );
    }
    return configured.sections.flatMap((section) => {
      const rows = section.rows.flatMap((row) => {
        const command = resolveCommandPayload(row.command);
        const title = renderOverride(row.title) ?? row.title.trim();
        if (!command || !title) return [];
        return [{
          title: fitListText(title, 60),
          description: row.description
            ? fitListText(renderOverride(row.description) ?? row.description, 110)
            : null,
          rowId: command,
          header: fitListText(command, 24),
        }];
      });
      if (rows.length === 0) return [];
      return [{
        title: fitListText(
          renderOverride(section.title) ?? section.title,
          60,
        ),
        rows,
      }];
    });
  };
  const buildConfiguredButtons = (
    configured: BotGroupMenuCarousel["cards"][number] | undefined,
  ): ListMessageButton[] => {
    if (configured?.buttons === null || configured?.buttons === undefined) {
      return [
        {
          type: "cta_url",
          text: "Site do BotAdmin",
          url: siteUrl,
        },
        ...(officialGroupUrl
          ? [
              {
                type: "cta_url" as const,
                text: "Grupo oficial",
                url: officialGroupUrl,
              },
            ]
          : []),
      ];
    }
    const resolved: ListMessageButton[] = [];
    for (const button of configured.buttons.slice(0, 2)) {
      const label = renderOverride(button.label) ?? button.label.trim();
      const value = renderOverride(button.value) ?? button.value.trim();
      if (!label || !value) continue;
      if (button.type === "url") {
        if (/^https?:\/\//i.test(value)) {
          resolved.push({ type: "cta_url", text: label, url: value });
        }
        continue;
      }
      if (button.type === "copy") {
        resolved.push({ type: "cta_copy", text: label, copyCode: value });
        continue;
      }
      const command = resolveCommandPayload(value);
      if (command) {
        resolved.push({ type: "quick_reply", text: label, id: command });
      }
    }
    return resolved;
  };
  const cards = await Promise.all(
    menuKinds.map(async (menuKind) => {
      const cardKind = cardKindByMenuKind[menuKind];
      const configured = configuredCards.get(cardKind);
      const baseCopy = resolveBotAdminNativeMenuCopy(
        menuKind,
        params.groupName,
        params.botName,
      );
      const isRequestedCard =
        menuKind === params.kind ||
        (params.kind === "main" && menuKind === "commands");
      const copy = {
        ...baseCopy,
        title:
          renderOverride(configured?.title) ||
          (isRequestedCard ? renderOverride(params.titleOverride) : null) ||
          baseCopy.title,
        description:
          renderOverride(configured?.description) ||
          (isRequestedCard ? renderOverride(params.descriptionOverride) : null) ||
          baseCopy.description,
        footerText:
          renderOverride(configured?.footerText) ||
          (isRequestedCard ? renderOverride(params.footerOverride) : null) ||
          baseCopy.footerText,
        buttonText:
          renderOverride(configured?.listButtonText) || baseCopy.buttonText,
      };
      const sections = buildConfiguredSections(configured, menuKind);
      const selectedImage =
        configured?.imageUrl?.trim() ||
        configured?.imagePath?.trim() ||
        params.imagePath ||
        null;
      const media = await loadCardMedia(selectedImage, cardKind);
      const buttons = buildConfiguredButtons(configured);
      return {
        copy,
        sections,
        media,
        card: {
          title: copy.title,
          description: copy.description,
          footerText: copy.footerText,
          buttonText: copy.buttonText,
          lists: sections.length > 0
            ? [{ buttonText: copy.buttonText, sections }]
            : [],
          buttons,
          media,
        },
      };
    }),
  );
  const validCards = cards.filter(
    (entry) => entry.sections.length > 0 || entry.card.buttons.length > 0,
  );
  if (validCards.length === 0) return false;
  const first = validCards[0]!;

  try {
    await sendListMessage(client, {
      to: params.chatId,
      title: first.copy.title,
      description: first.copy.description,
      buttonText: first.copy.buttonText,
      footerText: first.copy.footerText,
      media: first.media,
      sections: first.sections,
      cards: validCards.map((entry) => entry.card),
      transport: DEFAULT_LIST_MESSAGE_TRANSPORT,
    });
    return true;
  } catch (error) {
    console.error("[bot-events] Falha ao enviar menu pelo sendList novo; tentando fallback por botões nativos", {
      chatId: params.chatId,
      kind: params.kind,
      error,
    });
    return false;
  }
};

